package taproom

// Feasibility spike: 2/3 Game round engine with stakes, commit-reveal,
// permissionless settlement, pull payouts, and a time-window weekly streak.

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

const (
	denom       = "ugnot"
	weekSeconds = int64(604800)
	// Unix time zero fell on a Thursday; 4 days shifts week boundaries to Monday 00:00 UTC.
	weekOffset = int64(345600)

	pointsPlay = int64(10)
	pointsWin  = int64(30)
	streakStep = int64(4)
	streakCap  = int64(20)
	freezeCost = int64(40)
	maxFreezes = 2

	// Protocol fee in basis points (50 = 0.5%), taken from the pot of a completed round only.
	feeBps   = int64(50)
	bpsTotal = int64(10000)
)

var entryFee int64 = 1000000

var (
	feeRecipient address // set once at deploy; can only withdraw accrued fees
	feesAccrued  int64
)

func init() {
	feeRecipient = unsafe.OriginCaller()
}

// nowOverride lets tests control time; zero means use the block time.
var nowOverride int64

type Entry struct {
	Commit   string
	Revealed bool
	Pick     int64
}

type Round struct {
	ID        int
	CommitEnd int64
	RevealEnd int64
	Players   []address
	Entries   *avl.Tree // address -> *Entry
	Settled   bool
	Pot       int64
	Fee       int64
	Winners   []address
}

type Player struct {
	Lifetime  int64
	Spent     int64
	HasPlayed bool
	LastWeek  int64
	Streak    int64
	Freezes   int
}

var (
	rounds    []*Round
	players   = avl.NewTree() // address -> *Player
	claimable = avl.NewTree() // address -> int64
)

func now() int64 {
	if nowOverride != 0 {
		return nowOverride
	}
	return time.Now().Unix()
}

// weekIndex returns the Monday-00:00-UTC-aligned week number of a Unix timestamp.
func weekIndex(ts int64) int64 {
	d := ts - weekOffset
	w := d / weekSeconds
	if d%weekSeconds < 0 {
		w--
	}
	return w
}

// CommitHash is the value a player submits when joining: sha256("<pick>:<salt>") as hex.
func CommitHash(pick int64, salt string) string {
	sum := sha256.Sum256([]byte(strconv.FormatInt(pick, 10) + ":" + salt))
	return hex.EncodeToString(sum[:])
}

func mustUser(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("direct user call required")
	}
	return cur.Previous().Address()
}

func getRound(id int) *Round {
	if id < 0 || id >= len(rounds) {
		panic("unknown round")
	}
	return rounds[id]
}

func getPlayer(a address) *Player {
	v := players.Get(a.String())
	if v == nil {
		p := &Player{}
		players.Set(a.String(), p)
		return p
	}
	return v.(*Player)
}

func credit(a address, amt int64) {
	cur := int64(0)
	if v := claimable.Get(a.String()); v != nil {
		cur = v.(int64)
	}
	claimable.Set(a.String(), cur+amt)
}

// NewRound opens a round. commitSecs and revealSecs are window lengths in seconds.
func NewRound(cur realm, commitSecs, revealSecs int64) int {
	if commitSecs <= 0 || revealSecs <= 0 {
		panic("windows must be positive")
	}
	t := now()
	r := &Round{
		ID:        len(rounds),
		CommitEnd: t + commitSecs,
		RevealEnd: t + commitSecs + revealSecs,
		Entries:   avl.NewTree(),
	}
	rounds = append(rounds, r)
	return r.ID
}

// Join deposits the entry fee and stores a hidden pick.
func Join(cur realm, roundID int, commit string) {
	caller := mustUser(cur)
	r := getRound(roundID)
	if now() >= r.CommitEnd {
		panic("commit window closed")
	}
	if len(commit) != 64 {
		panic("commit must be 64 hex chars")
	}
	if r.Entries.Has(caller.String()) {
		panic("already joined")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom || sent[0].Amount != entryFee {
		panic("must send exactly the entry fee in ugnot")
	}
	r.Entries.Set(caller.String(), &Entry{Commit: commit})
	r.Players = append(r.Players, caller)
	r.Pot += entryFee
}

// Reveal opens the pick; it must match the commit. Counts as a play for points and streak.
func Reveal(cur realm, roundID int, pick int64, salt string) {
	caller := mustUser(cur)
	r := getRound(roundID)
	t := now()
	if t < r.CommitEnd || t >= r.RevealEnd {
		panic("not in reveal window")
	}
	v := r.Entries.Get(caller.String())
	if v == nil {
		panic("not a player in this round")
	}
	e := v.(*Entry)
	if e.Revealed {
		panic("already revealed")
	}
	if pick < 0 || pick > 100 {
		panic("pick must be 0..100")
	}
	if CommitHash(pick, salt) != e.Commit {
		panic("reveal does not match commit")
	}
	e.Revealed = true
	e.Pick = pick
	awardPlay(caller, t)
}

// Settle can be called by anyone once the reveal window has closed.
func Settle(cur realm, roundID int) {
	r := getRound(roundID)
	if now() < r.RevealEnd {
		panic("reveal window still open")
	}
	if r.Settled {
		panic("already settled")
	}
	r.Settled = true // effects before any payout bookkeeping

	var revealers []address
	var sum int64
	for _, p := range r.Players {
		e := r.Entries.Get(p.String()).(*Entry)
		if e.Revealed {
			revealers = append(revealers, p)
			sum += e.Pick
		}
	}
	n := int64(len(revealers))

	// Fewer than two reveals: void round, everyone is refunded.
	if n < 2 {
		for _, p := range r.Players {
			credit(p, entryFee)
		}
		return
	}

	// Winner is closest to 2/3 of the average: minimise |3*n*pick - 2*sum| (integer math).
	best := int64(-1)
	var winners []address
	for _, p := range revealers {
		e := r.Entries.Get(p.String()).(*Entry)
		d := 3*n*e.Pick - 2*sum
		if d < 0 {
			d = -d
		}
		if best < 0 || d < best {
			best = d
			winners = []address{p}
		} else if d == best {
			winners = append(winners, p)
		}
	}

	// Completed round (at least two reveals): take the fee, split the rest.
	fee := r.Pot * feeBps / bpsTotal
	r.Fee = fee
	feesAccrued += fee
	prize := r.Pot - fee

	count := int64(len(winners))
	share := prize / count
	rem := prize - share*count
	for i, w := range winners {
		amt := share
		if i == 0 {
			amt += rem
		}
		credit(w, amt)
		getPlayer(w).Lifetime += pointsWin - pointsPlay
	}
	r.Winners = winners
}

// Claim pays out the caller's balance (pull payment).
func Claim(cur realm) {
	caller := mustUser(cur)
	v := claimable.Get(caller.String())
	if v == nil || v.(int64) <= 0 {
		panic("nothing to claim")
	}
	amt := v.(int64)
	claimable.Set(caller.String(), int64(0)) // effects before interaction
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin(denom, amt)))
}

// WithdrawFees sends accrued protocol fees to the fee recipient. It touches nothing else.
func WithdrawFees(cur realm) {
	caller := mustUser(cur)
	if caller != feeRecipient {
		panic("only the fee recipient can withdraw fees")
	}
	amt := feesAccrued
	if amt <= 0 {
		panic("no fees to withdraw")
	}
	feesAccrued = 0 // effects before interaction
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin(denom, amt)))
}

func awardPlay(a address, ts int64) {
	p := getPlayer(a)
	w := weekIndex(ts)
	if !p.HasPlayed {
		p.Streak = 1
		p.LastWeek = w
	} else {
		g := w - p.LastWeek
		if g >= 1 {
			if g == 1 {
				p.Streak++
			} else {
				missed := int(g - 1)
				if p.Freezes >= missed {
					p.Freezes -= missed
					p.Streak++
				} else {
					// not enough freezes: the streak resets and every held freeze is used up
					p.Streak = 1
					p.Freezes = 0
				}
			}
			p.LastWeek = w
		}
	}
	p.HasPlayed = true
	bonus := streakStep * p.Streak
	if bonus > streakCap {
		bonus = streakCap
	}
	p.Lifetime += pointsPlay + bonus
}

// BuyFreeze spends points on a streak freeze (max 2 held).
func BuyFreeze(cur realm) {
	caller := mustUser(cur)
	p := getPlayer(caller)
	if p.Freezes >= maxFreezes {
		panic("freeze limit reached")
	}
	if p.Lifetime-p.Spent < freezeCost {
		panic("not enough points")
	}
	p.Spent += freezeCost
	p.Freezes++
}

// Views (non-crossing)

func Claimable(a address) int64 {
	if v := claimable.Get(a.String()); v != nil {
		return v.(int64)
	}
	return 0
}

func PlayerStats(a address) (lifetime, spendable, streak int64, freezes int) {
	v := players.Get(a.String())
	if v == nil {
		return 0, 0, 0, 0
	}
	p := v.(*Player)
	return p.Lifetime, p.Lifetime - p.Spent, p.Streak, p.Freezes
}

func Render(path string) string {
	var sb strings.Builder
	sb.WriteString("# Taproom spike\n\n")
	sb.WriteString("Rounds: " + strconv.Itoa(len(rounds)) + "\n\n")
	for _, r := range rounds {
		status := "open"
		if r.Settled {
			status = "settled"
		}
		sb.WriteString("- round " + strconv.Itoa(r.ID) + ": " + status +
			", players " + strconv.Itoa(len(r.Players)) +
			", pot " + strconv.FormatInt(r.Pot, 10) + " ugnot\n")
	}
	return sb.String()
}

package main

import (
	"gno.land/r/gov/dao"
	valset "gno.land/r/sys/validators/v0"
)

func main(cur realm) {
	r := valset.NewValidatorProposalRequest(
		cross(cur),
		[]valset.ValoperChange{
			valset.NewValoperChange(address("g1aeddlftlfk27ret5rf750d7w5dume3kcsm8r8m"), 167),
			valset.NewValoperChange(address("g1n9y62agq998jt8w59az60xcqlftjknjg2grhn4"), 167),
		},
		"Set validators gno-core-validator-1 and samourai-crew-1 to voting power 167",
		"Share gno-core-validator-1's voting power with samourai-crew-1: both at 167, so blocks keep committing while either of them is down.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}

package hearthbounty

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1x582angdzrqadgv4382j6y7ju6fj5wll6yuuq4/hearthcore/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/r/nt/grc20reg/v0"
)

type contributorRefund struct {
	addr   address
	amount int64
}

// ValidateEscrowToken verifies that a requested settlement token key matches
// the canonical 1:1 ugnot-backed wrapped GNOT key registered in grc20reg.
func ValidateEscrowToken(tokenKey string) {
	if strings.TrimSpace(tokenKey) != EscrowTokenKey {
		panic("hearthbounty: only 1:1 ugnot-backed wugnot escrow is accepted")
	}
}

func validateEscrowAmount(amount, minAmount int64) int64 {
	if amount < minAmount {
		panic("hearthbounty: escrow amount is below minimum required (100000 wugnot)")
	}
	if amount > MaxEscrowUgnot {
		panic("hearthbounty: escrow amount exceeds single-bounty safety ceiling")
	}
	return amount
}

// SetArbiter transfers dispute-resolution authority to a new valid Gno address.
func SetArbiter(cur realm, next address) {
	caller := cur.Previous().Address()
	if caller != arbiter {
		panic("hearthbounty: only current arbiter may transfer arbiter role")
	}
	if !next.IsValid() {
		panic("hearthbounty: next arbiter address is invalid")
	}
	arbiter = next
	chain.Emit(
		"ArbiterUpdated",
		"previous", string(caller),
		"arbiter", string(next),
	)
}

// RegisterProfile creates or updates a builder or autonomous AI agent profile.
// Providing a non-empty agentEndpoint marks the profile as an MCP-capable AI agent.
func RegisterProfile(cur realm, handle, bio, skills, agentEndpoint string) {
	caller := cur.Previous().Address()
	cleanHandle := hearthcore.ValidateText("handle", handle, 2, hearthcore.MaxHandleLen)
	cleanBio := hearthcore.ValidateText("bio", bio, 0, hearthcore.MaxBioLen)
	cleanSkills := hearthcore.ValidateText("skills", skills, 0, hearthcore.MaxSkillsLen)
	cleanEndpoint := hearthcore.ValidateText("agentEndpoint", agentEndpoint, 0, hearthcore.MaxEndpointLen)

	p := getOrCreateProfile(caller, runtime.ChainHeight())
	wasAgent := p.IsAgent
	p.Handle = cleanHandle
	p.Bio = cleanBio
	p.Skills = cleanSkills
	p.AgentEndpoint = cleanEndpoint
	p.IsAgent = cleanEndpoint != ""

	if !wasAgent && p.IsAgent {
		agentCount++
	} else if wasAgent && !p.IsAgent {
		agentCount--
	}

	chain.Emit(
		"ProfileRegistered",
		"address", string(caller),
		"handle", cleanHandle,
		"is_agent", strconv.FormatBool(p.IsAgent),
	)
}

// PostBounty creates a new micro-bounty funded with pre-approved 1:1 ugnot-backed
// wugnot via gno.land/r/nt/grc20reg/v0.
// Requires a direct EOA call (AssertOriginCall + cur.Previous().IsUserCall()).
func PostBounty(cur realm, title, spec, category string, rewardUgnot int64, deadlineBlocks int64) uint64 {
	runtime.AssertOriginCall()
	if !cur.Previous().IsUserCall() {
		panic("hearthbounty: direct EOA call required to fund escrow")
	}

	amount := validateEscrowAmount(rewardUgnot, hearthcore.MinRewardUgnot)
	cleanTitle := hearthcore.ValidateText("title", title, 4, hearthcore.MaxTitleLen)
	cleanSpec := hearthcore.ValidateText("spec", spec, 10, hearthcore.MaxSpecLen)
	cat, ok := hearthcore.ParseCategory(category)
	if !ok {
		panic("hearthbounty: invalid category (use realm, tool, audit, docs, or agent)")
	}
	blocks := hearthcore.ValidateDeadlineBlocks(deadlineBlocks)

	sponsor := cur.Previous().Address()
	// Pull pre-approved wugnot into realm custody before mutating bounty state.
	// Panics atomically if sponsor balance or allowance is insufficient.
	grc20reg.TransferFrom(0, cur, EscrowTokenKey, sponsor, cur.Address(), amount)

	height := runtime.ChainHeight()
	nextID := uint64(bountySeq.Next())

	rec := &bountyRecord{
		ID:                 nextID,
		Title:              cleanTitle,
		Spec:               cleanSpec,
		Category:           cat,
		Status:             hearthcore.StatusOpen,
		Sponsor:            sponsor,
		EscrowUgnot:        amount,
		InitialUgnot:       amount,
		SponsorFundedUgnot: amount,
		DonorShares:        avl.NewTree(),
		DeadlineBlocks:     blocks,
		CreatedHeight:      height,
	}

	bounties.Set(bountyKey(nextID), rec)
	openCount++
	totalEscrowUgnot += amount

	sp := getOrCreateProfile(sponsor, height)
	sp.PostedCount++
	sp.SponsoredUgnot += amount

	chain.Emit(
		"BountyPosted",
		"id", strconv.FormatUint(nextID, 10),
		"sponsor", string(sponsor),
		"category", string(cat),
		"escrow_token", EscrowTokenKey,
		"escrow_ugnot", strconv.FormatInt(amount, 10),
		"deadline_blocks", strconv.FormatInt(blocks, 10),
	)

	return nextID
}

// TopUpBounty allows supporters or the sponsor to add pre-approved wugnot
// (>= 0.10 GNOT) into an Open or Claimed bounty. Per-contributor custody is
// tracked in an AVL donor ledger so cancellations and dispute splits refund
// each contributor directly instead of handing external coins to the sponsor.
func TopUpBounty(cur realm, id uint64, amountUgnot int64) int64 {
	runtime.AssertOriginCall()
	if !cur.Previous().IsUserCall() {
		panic("hearthbounty: direct EOA call required to top up escrow")
	}

	amount := validateEscrowAmount(amountUgnot, MinTopUpUgnot)
	donor := cur.Previous().Address()
	b := validateTopUpTarget(donor, id, amount)

	grc20reg.TransferFrom(0, cur, EscrowTokenKey, donor, cur.Address(), amount)

	if donor == b.Sponsor {
		b.SponsorFundedUgnot += amount
	} else {
		if b.DonorShares == nil {
			b.DonorShares = avl.NewTree()
		}
		key := string(donor)
		prev := int64(0)
		if raw := b.DonorShares.Get(key); raw != nil {
			prev = raw.(int64)
		}
		b.DonorShares.Set(key, prev+amount)
		b.ExternalTopUpUgnot += amount
	}

	b.EscrowUgnot += amount
	b.TopUpCount++
	totalEscrowUgnot += amount

	dp := getOrCreateProfile(donor, runtime.ChainHeight())
	dp.SponsoredUgnot += amount

	chain.Emit(
		"BountyToppedUp",
		"id", strconv.FormatUint(id, 10),
		"donor", string(donor),
		"added_ugnot", strconv.FormatInt(amount, 10),
		"escrow_ugnot", strconv.FormatInt(b.EscrowUgnot, 10),
	)

	return b.EscrowUgnot
}

func validateTopUpTarget(donor address, id uint64, amount int64) *bountyRecord {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusOpen && b.Status != hearthcore.StatusClaimed {
		panic("hearthbounty: can only top up open or claimed bounties")
	}
	if b.Claimant != "" && donor == b.Claimant {
		panic("hearthbounty: active claimant cannot top up own claimed bounty")
	}
	if b.EscrowUgnot+amount > MaxEscrowUgnot {
		panic("hearthbounty: escrow total exceeds single-bounty safety ceiling")
	}
	if donor != b.Sponsor && b.DonorShares != nil && !b.DonorShares.Has(string(donor)) && b.DonorShares.Size() >= MaxExternalDonors {
		panic("hearthbounty: external donor cap reached for this bounty")
	}
	return b
}

// ClaimBounty reserves an open bounty for a builder or autonomous AI agent.
// Sponsors and external escrow contributors cannot claim the bounty they funded.
func ClaimBounty(cur realm, id uint64, agentNote string) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusOpen {
		panic("hearthbounty: bounty is not open for claiming")
	}

	caller := cur.Previous().Address()
	if caller == b.Sponsor {
		panic("hearthbounty: sponsor cannot claim own bounty")
	}
	if b.DonorShares != nil && b.DonorShares.Has(string(caller)) {
		panic("hearthbounty: escrow contributor cannot claim own funded bounty")
	}
	cleanNote := hearthcore.ValidateText("agentNote", agentNote, 0, hearthcore.MaxNoteLen)

	height := runtime.ChainHeight()
	transitionStatus(b, hearthcore.StatusClaimed)
	b.Claimant = caller
	b.ClaimNote = cleanNote
	b.ClaimedHeight = height
	b.DeadlineHeight = height + b.DeadlineBlocks

	hp := getOrCreateProfile(caller, height)
	hp.ClaimedCount++

	chain.Emit(
		"BountyClaimed",
		"id", strconv.FormatUint(id, 10),
		"claimant", string(caller),
		"deadline_height", strconv.FormatInt(b.DeadlineHeight, 10),
	)
}

// ReleaseExpiredClaim returns a claimed bounty to Open when either the claimant
// voluntarily steps down or ChainHeight() reaches DeadlineHeight.
func ReleaseExpiredClaim(cur realm, id uint64) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusClaimed {
		panic("hearthbounty: bounty is not currently claimed")
	}

	caller := cur.Previous().Address()
	height := runtime.ChainHeight()
	if caller != b.Claimant && height < b.DeadlineHeight {
		panic("hearthbounty: claim deadline has not expired yet")
	}

	prevClaimant := b.Claimant
	if raw := profiles.Get(string(prevClaimant)); raw != nil {
		p := raw.(*profileRecord)
		if p.ClaimedCount > 0 {
			p.ClaimedCount--
		}
	}

	transitionStatus(b, hearthcore.StatusOpen)
	b.Claimant = ""
	b.ClaimNote = ""
	b.ClaimedHeight = 0
	b.DeadlineHeight = 0
	b.SubmittedHeight = 0
	b.ReviewDeadlineHeight = 0
	b.ProofURL = ""
	b.ProofDigest = ""
	b.ProofSummary = ""
	b.RevisionFeedback = ""

	chain.Emit(
		"ClaimReleased",
		"id", strconv.FormatUint(id, 10),
		"previous_claimant", string(prevClaimant),
		"released_by", string(caller),
	)
}

// SubmitProof records an HTTPS deliverable URL, SHA-256 content digest, and
// implementation summary, opening a deterministic sponsor review window.
func SubmitProof(cur realm, id uint64, proofURL, proofDigest, summary string) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusClaimed {
		panic("hearthbounty: bounty must be claimed before submitting proof")
	}

	caller := cur.Previous().Address()
	if caller != b.Claimant {
		panic("hearthbounty: only the active claimant may submit proof")
	}

	cleanURL := ValidateProofURL(proofURL)
	cleanDigest := hearthcore.ValidateProofDigest(proofDigest)
	cleanSummary := hearthcore.ValidateText("summary", summary, 6, hearthcore.MaxNoteLen)
	height := runtime.ChainHeight()

	transitionStatus(b, hearthcore.StatusSubmitted)
	b.ProofURL = cleanURL
	b.ProofDigest = cleanDigest
	b.ProofSummary = cleanSummary
	b.SubmittedHeight = height
	b.ReviewDeadlineHeight = height + b.DeadlineBlocks
	b.SubmissionCount++
	b.RevisionFeedback = ""

	chain.Emit(
		"ProofSubmitted",
		"id", strconv.FormatUint(id, 10),
		"claimant", string(caller),
		"proof_digest", cleanDigest,
		"review_deadline_height", strconv.FormatInt(b.ReviewDeadlineHeight, 10),
		"submission_count", strconv.FormatUint(b.SubmissionCount, 10),
	)
}

// RequestRevision lets the sponsor send a submitted bounty back to Claimed with
// actionable feedback and a refreshed claim deadline window.
func RequestRevision(cur realm, id uint64, feedback string) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusSubmitted {
		panic("hearthbounty: bounty has no pending submission")
	}

	caller := cur.Previous().Address()
	if caller != b.Sponsor {
		panic("hearthbounty: only the sponsor may request a revision")
	}

	cleanFeedback := hearthcore.ValidateText("feedback", feedback, 4, hearthcore.MaxNoteLen)
	transitionStatus(b, hearthcore.StatusClaimed)
	b.RevisionFeedback = cleanFeedback
	b.ReviewDeadlineHeight = 0
	b.DeadlineHeight = runtime.ChainHeight() + b.DeadlineBlocks

	chain.Emit(
		"RevisionRequested",
		"id", strconv.FormatUint(id, 10),
		"sponsor", string(caller),
		"new_deadline_height", strconv.FormatInt(b.DeadlineHeight, 10),
	)
}

// ApproveAndSettle releases the full wugnot escrow to the claimant, records a
// 1-5 quality rating, and updates on-chain reputation using CEI ordering.
func ApproveAndSettle(cur realm, id uint64, rating uint8, reviewNote string) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusSubmitted {
		panic("hearthbounty: bounty is not awaiting approval")
	}

	caller := cur.Previous().Address()
	if caller != b.Sponsor {
		panic("hearthbounty: only the sponsor may approve and settle")
	}

	validRating := hearthcore.ValidateRating(rating)
	cleanNote := hearthcore.ValidateText("reviewNote", reviewNote, 0, hearthcore.MaxNoteLen)
	settleFullToClaimant(cur, b, validRating, cleanNote, "BountySettled")
}

// ExpireSubmission is callable by anyone once ChainHeight() reaches
// ReviewDeadlineHeight without sponsor action. It settles 100% of the escrow
// to the claimant so sponsors cannot hold delivered work hostage forever.
func ExpireSubmission(cur realm, id uint64) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusSubmitted {
		panic("hearthbounty: bounty has no pending submission")
	}
	if runtime.ChainHeight() < b.ReviewDeadlineHeight {
		panic("hearthbounty: submission review window has not expired yet")
	}

	settleFullToClaimant(cur, b, 0, "[Auto-Settled] Sponsor review window expired", "SubmissionExpiredSettled")
}

func settleFullToClaimant(cur realm, b *bountyRecord, rating uint8, reviewNote, eventName string) {
	payout := b.EscrowUgnot
	recipient := b.Claimant
	height := runtime.ChainHeight()

	// Effects before external token transfer (CEI).
	b.EscrowUgnot = 0
	b.SponsorFundedUgnot = 0
	b.ExternalTopUpUgnot = 0
	b.DonorShares = avl.NewTree()
	b.PayoutUgnot = payout
	b.Rating = rating
	b.ReviewNote = reviewNote
	b.SettledHeight = height
	transitionStatus(b, hearthcore.StatusSettled)
	totalEscrowUgnot -= payout
	totalSettledUgnot += payout

	hp := getOrCreateProfile(recipient, height)
	hp.SettledCount++
	hp.EarnedUgnot += payout
	if rating > 0 {
		hp.RatingSum += uint64(rating)
		hp.RatingCount++
	}

	sp := getOrCreateProfile(b.Sponsor, height)
	sp.SponsoredSettled++

	if payout > 0 {
		grc20reg.Transfer(0, cur, EscrowTokenKey, recipient, payout)
	}

	chain.Emit(
		eventName,
		"id", strconv.FormatUint(b.ID, 10),
		"sponsor", string(b.Sponsor),
		"claimant", string(recipient),
		"payout_ugnot", strconv.FormatInt(payout, 10),
		"rating", strconv.Itoa(int(rating)),
	)
}

// CancelBounty cancels an Open bounty and refunds each contributor directly.
// Third-party top-up coins are returned strictly to their original donors,
// never to the sponsor, and refunded sponsorship credits are reversed.
func CancelBounty(cur realm, id uint64) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusOpen {
		panic("hearthbounty: only open bounties can be cancelled")
	}

	caller := cur.Previous().Address()
	if caller != b.Sponsor {
		panic("hearthbounty: only the sponsor may cancel")
	}

	totalRefund := b.EscrowUgnot
	sponsorRefund := b.SponsorFundedUgnot
	externalRefundTotal := int64(0)
	donorRefunds := make([]contributorRefund, 0)
	if b.DonorShares != nil {
		b.DonorShares.Iterate("", "", func(key string, val any) bool {
			amt := val.(int64)
			if amt > 0 {
				donorRefunds = append(donorRefunds, contributorRefund{
					addr:   address(key),
					amount: amt,
				})
				externalRefundTotal += amt
			}
			return false
		})
	}
	if sponsorRefund+externalRefundTotal != totalRefund {
		panic("hearthbounty: internal escrow custody invariant mismatch")
	}

	// Effects before interactions (CEI).
	b.EscrowUgnot = 0
	b.SponsorFundedUgnot = 0
	b.ExternalTopUpUgnot = 0
	b.DonorShares = avl.NewTree()
	b.RefundUgnot = totalRefund
	transitionStatus(b, hearthcore.StatusCancelled)
	totalEscrowUgnot -= totalRefund
	totalRefundUgnot += totalRefund

	decrementSponsoredCredit(b.Sponsor, sponsorRefund)
	for _, dr := range donorRefunds {
		decrementSponsoredCredit(dr.addr, dr.amount)
	}

	if sponsorRefund > 0 {
		grc20reg.Transfer(0, cur, EscrowTokenKey, b.Sponsor, sponsorRefund)
	}
	for _, dr := range donorRefunds {
		grc20reg.Transfer(0, cur, EscrowTokenKey, dr.addr, dr.amount)
	}

	chain.Emit(
		"BountyCancelled",
		"id", strconv.FormatUint(id, 10),
		"sponsor", string(b.Sponsor),
		"sponsor_refund_ugnot", strconv.FormatInt(sponsorRefund, 10),
		"external_refund_ugnot", strconv.FormatInt(externalRefundTotal, 10),
		"refund_ugnot", strconv.FormatInt(totalRefund, 10),
	)
}

// OpenDispute escalates a submitted bounty to arbiter review and sets a
// deterministic dispute resolution timeout.
func OpenDispute(cur realm, id uint64, reason string) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusSubmitted {
		panic("hearthbounty: disputes can only be opened on submitted bounties")
	}

	caller := cur.Previous().Address()
	if caller != b.Sponsor && caller != b.Claimant {
		panic("hearthbounty: only sponsor or claimant may open a dispute")
	}

	cleanReason := hearthcore.ValidateText("reason", reason, 6, hearthcore.MaxNoteLen)
	height := runtime.ChainHeight()
	transitionStatus(b, hearthcore.StatusDisputed)
	b.DisputeReason = cleanReason
	b.DisputeOpenedBy = caller
	b.DisputedHeight = height
	b.DisputeDeadlineHeight = height + b.DeadlineBlocks

	chain.Emit(
		"DisputeOpened",
		"id", strconv.FormatUint(id, 10),
		"opened_by", string(caller),
		"dispute_deadline_height", strconv.FormatInt(b.DisputeDeadlineHeight, 10),
		"reason", cleanReason,
	)
}

// ResolveDispute settles a disputed bounty using deterministic basis-point math
// (hunterBps in 0..10000). The arbiter cannot resolve a bounty they are a party
// to, and any refunded portion is returned pro-rata to sponsor and external donors.
func ResolveDispute(cur realm, id uint64, hunterBps uint64, resolution string) {
	caller := cur.Previous().Address()
	if caller != arbiter {
		panic("hearthbounty: only the arbiter may resolve disputes")
	}

	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusDisputed {
		panic("hearthbounty: bounty is not disputed")
	}
	if caller == b.Sponsor || caller == b.Claimant {
		panic("hearthbounty: arbiter cannot resolve a bounty they are party to")
	}

	cleanResolution := hearthcore.ValidateText("resolution", resolution, 4, hearthcore.MaxNoteLen)
	settleDisputeSplit(cur, b, hunterBps, "[Arbiter Resolution] "+cleanResolution, caller, "DisputeResolved")
}

// ExpireDispute is callable by anyone once ChainHeight() reaches
// DisputeDeadlineHeight without arbiter action. It splits escrow 50/50
// (5000 bps to claimant, 5000 bps pro-rata back to contributors) so lost or
// conflicted arbiter keys can never trap escrowed wugnot forever.
func ExpireDispute(cur realm, id uint64) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusDisputed {
		panic("hearthbounty: bounty is not disputed")
	}
	if runtime.ChainHeight() < b.DisputeDeadlineHeight {
		panic("hearthbounty: dispute resolution window has not expired yet")
	}

	caller := cur.Previous().Address()
	settleDisputeSplit(cur, b, 5000, "[Timeout Split 50/50] Arbiter resolution window expired", caller, "DisputeExpiredSplit")
}

func settleDisputeSplit(cur realm, b *bountyRecord, hunterBps uint64, reviewNote string, resolver address, eventName string) {
	escrow := b.EscrowUgnot
	_, sponsorRefund := hearthcore.ComputeSplit(b.SponsorFundedUgnot, hunterBps)

	donorRefunds := make([]contributorRefund, 0)
	totalRefunds := sponsorRefund
	if b.DonorShares != nil {
		b.DonorShares.Iterate("", "", func(key string, val any) bool {
			amt := val.(int64)
			if amt > 0 {
				_, dRefund := hearthcore.ComputeSplit(amt, hunterBps)
				if dRefund > 0 {
					donorRefunds = append(donorRefunds, contributorRefund{
						addr:   address(key),
						amount: dRefund,
					})
					totalRefunds += dRefund
				}
			}
			return false
		})
	}
	hunterShare := escrow - totalRefunds
	height := runtime.ChainHeight()

	// Effects before interactions (CEI).
	b.EscrowUgnot = 0
	b.SponsorFundedUgnot = 0
	b.ExternalTopUpUgnot = 0
	b.DonorShares = avl.NewTree()
	b.PayoutUgnot = hunterShare
	b.RefundUgnot = totalRefunds
	b.ReviewNote = reviewNote
	b.SettledHeight = height
	transitionStatus(b, hearthcore.StatusSettled)
	totalEscrowUgnot -= escrow
	totalSettledUgnot += hunterShare
	totalRefundUgnot += totalRefunds

	if hunterShare > 0 {
		hp := getOrCreateProfile(b.Claimant, height)
		hp.SettledCount++
		hp.EarnedUgnot += hunterShare
	}
	decrementSponsoredCredit(b.Sponsor, sponsorRefund)
	for _, dr := range donorRefunds {
		decrementSponsoredCredit(dr.addr, dr.amount)
	}

	if hunterShare > 0 {
		grc20reg.Transfer(0, cur, EscrowTokenKey, b.Claimant, hunterShare)
	}
	if sponsorRefund > 0 {
		grc20reg.Transfer(0, cur, EscrowTokenKey, b.Sponsor, sponsorRefund)
	}
	for _, dr := range donorRefunds {
		grc20reg.Transfer(0, cur, EscrowTokenKey, dr.addr, dr.amount)
	}

	chain.Emit(
		eventName,
		"id", strconv.FormatUint(b.ID, 10),
		"resolver", string(resolver),
		"hunter_bps", strconv.FormatUint(hunterBps, 10),
		"hunter_ugnot", strconv.FormatInt(hunterShare, 10),
		"sponsor_refund_ugnot", strconv.FormatInt(sponsorRefund, 10),
		"total_refund_ugnot", strconv.FormatInt(totalRefunds, 10),
	)
}

func normalizeFilter(raw string) string {
	return strings.ToLower(strings.TrimSpace(raw))
}

package hearthbounty

import (
	"chain/runtime"
	"sort"

	"gno.land/p/g1x582angdzrqadgv4382j6y7ju6fj5wll6yuuq4/hearthcore/v0"
	"gno.land/r/nt/grc20reg/v0"
)

// Arbiter returns the current dispute arbiter address.
func Arbiter() address {
	return arbiter
}

// PkgPath returns the canonical Gno.land package path of this realm.
func PkgPath() string {
	return realmPkgPath
}

// EscrowToken returns the canonical grc20reg key used for 1:1 ugnot-backed escrow.
func EscrowToken() string {
	return EscrowTokenKey
}

// EscrowRealmAddress returns the derived realm address that holds escrowed wugnot.
func EscrowRealmAddress() address {
	return realmAddress
}

// EscrowBalance returns the current wugnot balance of addr from grc20reg.
func EscrowBalance(addr address) int64 {
	return grc20reg.MustGet(EscrowTokenKey).BalanceOf(addr)
}

// EscrowAllowance returns how much wugnot owner has approved this realm to pull.
func EscrowAllowance(owner address) int64 {
	return grc20reg.MustGet(EscrowTokenKey).Allowance(owner, realmAddress)
}

// GetStats returns an immutable snapshot of protocol counters and escrow totals.
func GetStats() BoardStats {
	return BoardStats{
		TotalBounties:     bounties.Size(),
		OpenCount:         openCount,
		ClaimedCount:      claimedCount,
		SubmittedCount:    submittedCount,
		DisputedCount:     disputedCount,
		SettledCount:      settledCount,
		CancelledCount:    cancelledCount,
		ProfileCount:      profiles.Size(),
		AgentCount:        agentCount,
		TotalEscrowUgnot:  totalEscrowUgnot,
		TotalSettledUgnot: totalSettledUgnot,
		TotalRefundUgnot:  totalRefundUgnot,
	}
}

// GetBounty returns a value copy of a single bounty by ID.
func GetBounty(id uint64) (BountyView, bool) {
	b, ok := getBountyRecord(id)
	if !ok {
		return BountyView{}, false
	}
	return toBountyView(b), true
}

// GetDonorContribution returns the external top-up ugnot currently held in
// custody for donor on bounty id (0 if none or if donor is the sponsor).
func GetDonorContribution(id uint64, donor address) int64 {
	b, ok := getBountyRecord(id)
	if !ok || b.DonorShares == nil {
		return 0
	}
	if raw := b.DonorShares.Get(string(donor)); raw != nil {
		return raw.(int64)
	}
	return 0
}

// GetProfile returns a value copy of a builder or AI agent profile.
func GetProfile(addr address) (ProfileView, bool) {
	raw := profiles.Get(string(addr))
	if raw == nil {
		return ProfileView{}, false
	}
	return toProfileView(raw.(*profileRecord)), true
}

// ExportStatsJSON returns global protocol stats as deterministic JSON for MCP agents.
func ExportStatsJSON() string {
	s := GetStats()
	return hearthcore.NewJSONObject().
		Str("realm_path", realmPkgPath).
		Str("web_path", realmWebBase).
		Str("escrow_token", EscrowTokenKey).
		Str("escrow_address", string(realmAddress)).
		Str("arbiter", string(arbiter)).
		Int64("chain_height", runtime.ChainHeight()).
		Int64("total_bounties", int64(s.TotalBounties)).
		Int64("open_count", int64(s.OpenCount)).
		Int64("claimed_count", int64(s.ClaimedCount)).
		Int64("submitted_count", int64(s.SubmittedCount)).
		Int64("disputed_count", int64(s.DisputedCount)).
		Int64("settled_count", int64(s.SettledCount)).
		Int64("cancelled_count", int64(s.CancelledCount)).
		Int64("profile_count", int64(s.ProfileCount)).
		Int64("agent_count", int64(s.AgentCount)).
		Int64("total_escrow_ugnot", s.TotalEscrowUgnot).
		Int64("total_settled_ugnot", s.TotalSettledUgnot).
		Int64("total_refund_ugnot", s.TotalRefundUgnot).
		String()
}

// ExportBountyJSON returns a single bounty as deterministic JSON (or {"found":false}).
func ExportBountyJSON(id uint64) string {
	b, ok := getBountyRecord(id)
	if !ok {
		return `{"found":false}`
	}
	return encodeBountyJSON(b, true)
}

// ExportBountiesJSON lists bounties in reverse chronological order with optional
// status, category, and minimum reward filters for autonomous agent discovery.
func ExportBountiesJSON(statusFilter, categoryFilter string, minRewardUgnot int64, limit int) string {
	st := normalizeFilter(statusFilter)
	cat := normalizeFilter(categoryFilter)
	if limit <= 0 || limit > 100 {
		limit = 50
	}

	items := make([]string, 0)
	bounties.ReverseIterate("", "", func(_ string, val any) bool {
		b := val.(*bountyRecord)
		if st != "" && string(b.Status) != st {
			return false
		}
		if cat != "" && string(b.Category) != cat {
			return false
		}
		reward := effectiveReward(b)
		if minRewardUgnot > 0 && reward < minRewardUgnot {
			return false
		}
		items = append(items, encodeBountyJSON(b, false))
		return len(items) >= limit
	})

	return hearthcore.NewJSONObject().
		Int64("chain_height", runtime.ChainHeight()).
		Int64("count", int64(len(items))).
		Raw("bounties", hearthcore.JoinJSONArray(items)).
		String()
}

// ExportLeaderboardJSON returns deterministically sorted builders & AI agents.
func ExportLeaderboardJSON(limit int) string {
	if limit <= 0 || limit > 100 {
		limit = 25
	}
	ranked := rankedProfiles()
	if len(ranked) > limit {
		ranked = ranked[:limit]
	}

	items := make([]string, 0, len(ranked))
	for i, p := range ranked {
		items = append(items, encodeProfileJSON(p, i+1))
	}

	return hearthcore.NewJSONObject().
		Int64("count", int64(len(items))).
		Raw("leaderboard", hearthcore.JoinJSONArray(items)).
		String()
}

// ExportProfileJSON returns a single profile as deterministic JSON.
func ExportProfileJSON(addrStr string) string {
	raw := profiles.Get(addrStr)
	if raw == nil {
		return `{"found":false}`
	}
	p := raw.(*profileRecord)
	return encodeProfileJSON(p, 0)
}

func effectiveReward(b *bountyRecord) int64 {
	if b.EscrowUgnot > 0 {
		return b.EscrowUgnot
	}
	if b.PayoutUgnot > 0 {
		return b.PayoutUgnot
	}
	if b.RefundUgnot > 0 {
		return b.RefundUgnot
	}
	return b.InitialUgnot
}

func encodeBountyJSON(b *bountyRecord, includeFound bool) string {
	donorCount := int64(0)
	if b.DonorShares != nil {
		donorCount = int64(b.DonorShares.Size())
	}
	jb := hearthcore.NewJSONObject()
	if includeFound {
		jb.Bool("found", true)
	}
	jb.Uint64("id", b.ID).
		Str("title", b.Title).
		Str("spec", b.Spec).
		Str("category", string(b.Category)).
		Str("status", string(b.Status)).
		Str("sponsor", string(b.Sponsor)).
		Str("claimant", string(b.Claimant)).
		Str("claim_note", b.ClaimNote).
		Int64("escrow_ugnot", b.EscrowUgnot).
		Int64("initial_ugnot", b.InitialUgnot).
		Int64("sponsor_funded_ugnot", b.SponsorFundedUgnot).
		Int64("external_top_up_ugnot", b.ExternalTopUpUgnot).
		Int64("external_donor_count", donorCount).
		Int64("payout_ugnot", b.PayoutUgnot).
		Int64("refund_ugnot", b.RefundUgnot).
		Str("reward_formatted", hearthcore.FormatGNOT(effectiveReward(b))).
		Uint64("top_up_count", b.TopUpCount).
		Int64("deadline_blocks", b.DeadlineBlocks).
		Int64("created_height", b.CreatedHeight).
		Int64("claimed_height", b.ClaimedHeight).
		Int64("deadline_height", b.DeadlineHeight).
		Int64("submitted_height", b.SubmittedHeight).
		Int64("review_deadline_height", b.ReviewDeadlineHeight).
		Int64("disputed_height", b.DisputedHeight).
		Int64("dispute_deadline_height", b.DisputeDeadlineHeight).
		Int64("settled_height", b.SettledHeight).
		Str("proof_url", b.ProofURL).
		Str("proof_digest", b.ProofDigest).
		Str("proof_summary", b.ProofSummary).
		Uint64("submission_count", b.SubmissionCount).
		Str("revision_feedback", b.RevisionFeedback).
		Uint64("rating", uint64(b.Rating)).
		Str("review_note", b.ReviewNote).
		Str("dispute_reason", b.DisputeReason).
		Str("dispute_opened_by", string(b.DisputeOpenedBy))
	return jb.String()
}

func encodeProfileJSON(p *profileRecord, rank int) string {
	tier := hearthcore.ComputeTier(p.SettledCount, p.EarnedUgnot, p.RatingSum, p.RatingCount)
	jb := hearthcore.NewJSONObject()
	if rank == 0 {
		jb.Bool("found", true)
	} else {
		jb.Int64("rank", int64(rank))
	}
	jb.Str("address", string(p.Address)).
		Str("handle", p.Handle).
		Str("bio", p.Bio).
		Str("skills", p.Skills).
		Str("agent_endpoint", p.AgentEndpoint).
		Bool("is_agent", p.IsAgent).
		Str("tier", string(tier)).
		Uint64("posted_count", p.PostedCount).
		Uint64("claimed_count", p.ClaimedCount).
		Uint64("settled_count", p.SettledCount).
		Uint64("sponsored_settled", p.SponsoredSettled).
		Int64("earned_ugnot", p.EarnedUgnot).
		Str("earned_formatted", hearthcore.FormatGNOT(p.EarnedUgnot)).
		Int64("sponsored_ugnot", p.SponsoredUgnot).
		Str("rating_formatted", hearthcore.FormatRating(p.RatingSum, p.RatingCount)).
		Uint64("rating_sum", p.RatingSum).
		Uint64("rating_count", p.RatingCount)
	return jb.String()
}

type profileRankSlice []*profileRecord

func (s profileRankSlice) Len() int { return len(s) }
func (s profileRankSlice) Swap(i, j int) {
	s[i], s[j] = s[j], s[i]
}
func (s profileRankSlice) Less(i, j int) bool {
	a, b := s[i], s[j]
	if a.EarnedUgnot != b.EarnedUgnot {
		return a.EarnedUgnot > b.EarnedUgnot
	}
	if a.SettledCount != b.SettledCount {
		return a.SettledCount > b.SettledCount
	}
	if a.SponsoredUgnot != b.SponsoredUgnot {
		return a.SponsoredUgnot > b.SponsoredUgnot
	}
	return string(a.Address) < string(b.Address)
}

func rankedProfiles() []*profileRecord {
	list := make([]*profileRecord, 0, profiles.Size())
	profiles.Iterate("", "", func(_ string, val any) bool {
		list = append(list, val.(*profileRecord))
		return false
	})

	sort.Sort(profileRankSlice(list))
	return list
}

package hearthbounty

import (
	"chain/runtime"
	"net/url"
	"strconv"
	"strings"

	"gno.land/p/g1x582angdzrqadgv4382j6y7ju6fj5wll6yuuq4/hearthcore/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
)

func initRouter() {
	router = mux.NewRouter()
	router.HandleFunc("", renderHome)
	router.HandleFunc("page/{page}", renderHomePage)
	router.HandleFunc("category/{cat}", renderCategory)
	router.HandleFunc("bounty/{id}", renderBountyDetail)
	router.HandleFunc("post", renderPostPage)
	router.HandleFunc("leaderboard", renderLeaderboard)
	router.HandleFunc("profile/{addr}", renderProfilePage)
	router.HandleFunc("agents", renderAgentsHub)
	router.NotFoundHandler = renderNotFound
}

// Render serves the native gnoweb interface and machine-readable Markdown views.
// Strictly read-only; all dynamic inputs are sanitized via sanitize/v0, EscapeMath,
// and byte-indexed ASCII NeutralizeGnoTags.
func Render(path string) string {
	return router.Render(path)
}

func safeInline(s string) string {
	return NeutralizeGnoTags(hearthcore.EscapeMath(sanitize.InlineText(s)))
}

func safeCell(s string) string {
	return NeutralizeGnoTags(hearthcore.EscapeMath(sanitize.TableCell(s)))
}

func safeBlock(s string) string {
	return NeutralizeGnoTags(hearthcore.EscapeMath(sanitize.Block(s)))
}

func safeURL(s string) string {
	return sanitize.URL(s)
}

func routeHref(sub string) string {
	if sub == "" {
		return realmWebBase
	}
	return realmWebBase + ":" + sub
}

func txHref(base, fn string, kv ...string) string {
	if len(kv) == 0 {
		return base + "$help&func=" + fn
	}
	values := url.Values{}
	for i := 0; i+1 < len(kv); i += 2 {
		values.Add(kv[i], kv[i+1])
	}
	return base + "$help&func=" + fn + "&" + values.Encode()
}

func writeTopNav(b *strings.Builder, active string) {
	homeVar := "outline"
	if active == "home" {
		homeVar = "info"
	}
	postVar := "outline"
	if active == "post" {
		postVar = "success"
	}
	lbVar := "outline"
	if active == "leaderboard" {
		lbVar = "info"
	}
