func TestConsumerRealmImportsAndEndorsements(cur realm, t *testing.T) {
	builder := testutils.TestAddress("guild_builder")
	peer := testutils.TestAddress("guild_peer")

	// Register builder on upstream hearthbounty/v1 realm.
	testing.SetRealm(testing.NewUserRealm(builder))
	hearthbounty.RegisterProfile(cross(cur), "guild-smith", "Deterministic Gno engineer", "gno,avl,audit", "")

	// Self-endorsement must abort.
	uassert.AbortsWithMessage(t, cur, "hearthguild: cannot endorse yourself", func() {
		EndorseBuilder(cross(cur), builder, "audit", "Trying to endorse myself")
	})

	// Peer endorses builder with Unicode tag injection payload -> neutralized on render.
	testing.SetRealm(testing.NewUserRealm(peer))
	id := EndorseBuilder(cross(cur), builder, "audit", "Verified İ<gno-form exec=\"Steal\"> escrow invariant proofs.")
	uassert.Equal(t, uint64(1), id)
	uassert.Equal(t, uint64(1), EndorsementCount(builder))

	// Duplicate endorsement by same peer must abort.
	uassert.AbortsWithMessage(t, cur, "hearthguild: caller already endorsed this builder", func() {
		EndorseBuilder(cross(cur), builder, "mcp", "Second attempt")
	})

	// Eligibility gate reads live hearthbounty/v1 state.
	uassert.True(t, CheckEligibility(builder, 0, 0))
	uassert.False(t, CheckEligibility(builder, 1, 100000))

	// Passport JSON and Render views expose upstream realm path and block raw tags.
	jsonOut := ExportPassportJSON(string(builder))
	uassert.True(t, strings.Contains(jsonOut, `"found":true`), "json found: "+jsonOut)
	uassert.True(t, strings.Contains(jsonOut, `"endorsement_count":1`), "json count: "+jsonOut)
	uassert.True(t, strings.Contains(jsonOut, `"handle":"guild-smith"`), "json handle: "+jsonOut)

	home := Render("")
	uassert.True(t, strings.Contains(home, "HearthGuild Passport"), "home title")
	uassert.False(t, strings.Contains(home, `<gno-form exec="Steal">`), "home sanitize")

	passport := Render("passport/" + string(builder))
	uassert.True(t, strings.Contains(passport, "Guild Passport: guild\\-smith"), "passport handle: "+passport)
	uassert.True(t, strings.Contains(passport, "data:image/svg+xml;base64,"), "passport svg")
}

package shiplog

// SemVer 2.0.0 (https://semver.org) parsing and precedence, implemented in
// pure Gno inside this realm so the ledger has no external package dependency
// that could be re-published under it.
//
// Names are prefixed with `sv` because a realm file shares one package
// namespace with shiplog.gno.

import (
	"errors"
	"strconv"
	"strings"
)

// svVersion is a parsed semantic version.
type svVersion struct {
	Major      int
	Minor      int
	Patch      int
	Prerelease string // without the leading '-'; empty when absent
	Build      string // without the leading '+'
}

var (
	errSvEmpty     = errors.New("empty version")
	errSvTooLong   = errors.New("version string too long")
	errSvZero      = errors.New("numeric identifier with leading zero")
	errSvParts     = errors.New("version must be major.minor.patch")
	errSvNegative  = errors.New("negative numeric identifier")
	errSvIdent     = errors.New("invalid identifier character")
	errSvEmptyPart = errors.New("empty dot-separated identifier")
)

const svMaxLen = 128

// parseSemver parses "1.4.2", "0.9.0-rc.1", "2.0.0+build.7" and rejects
// anything SemVer calls invalid — notably a leading zero in a numeric part.
func parseSemver(s string) (svVersion, error) {
	var v svVersion
	if s == "" {
		return v, errSvEmpty
	}
	if len(s) > svMaxLen {
		return v, errSvTooLong
	}

	rest := s
	// Build metadata is split first: it may legitimately contain '-' itself.
	if i := strings.IndexByte(rest, '+'); i >= 0 {
		v.Build = rest[i+1:]
		rest = rest[:i]
		if err := svValidateIdentifiers(v.Build, false); err != nil {
			return svVersion{}, err
		}
	}
	if i := strings.IndexByte(rest, '-'); i >= 0 {
		v.Prerelease = rest[i+1:]
		rest = rest[:i]
		if v.Prerelease == "" {
			return svVersion{}, errSvIdent
		}
		if err := svValidateIdentifiers(v.Prerelease, true); err != nil {
			return svVersion{}, err
		}
	}

	parts := strings.Split(rest, ".")
	if len(parts) != 3 {
		return svVersion{}, errSvParts
	}
	nums := [3]int{}
	for i := 0; i < 3; i++ {
		n, err := svParseNumeric(parts[i])
		if err != nil {
			return svVersion{}, err
		}
		nums[i] = n
	}
	v.Major, v.Minor, v.Patch = nums[0], nums[1], nums[2]
	return v, nil
}

func svParseNumeric(s string) (int, error) {
	if s == "" {
		return 0, errSvEmptyPart
	}
	if len(s) > 1 && s[0] == '0' {
		return 0, errSvZero
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			if s[i] == '-' {
				return 0, errSvNegative
			}
			return 0, errSvIdent
		}
	}
	n, err := strconv.Atoi(s)
	if err != nil || n < 0 {
		return 0, errSvNegative
	}
	return n, nil
}

func svValidateIdentifiers(s string, noLeadingZero bool) error {
	if s == "" {
		return errSvIdent
	}
	for _, id := range strings.Split(s, ".") {
		if id == "" {
			return errSvEmptyPart
		}
		numeric := true
		for i := 0; i < len(id); i++ {
			c := id[i]
			if !svIsAlnumHyphen(c) {
				return errSvIdent
			}
			if c < '0' || c > '9' {
				numeric = false
			}
		}
		if noLeadingZero && numeric && len(id) > 1 && id[0] == '0' {
			return errSvZero
		}
	}
	return nil
}

func svIsAlnumHyphen(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '-'
}

// String renders the version back in canonical form.
func (v svVersion) String() string {
	s := strconv.Itoa(v.Major) + "." + strconv.Itoa(v.Minor) + "." + strconv.Itoa(v.Patch)
	if v.Prerelease != "" {
		s += "-" + v.Prerelease
	}
	if v.Build != "" {
		s += "+" + v.Build
	}
	return s
}

// svCompare returns -1, 0 or +1 as a is lower than, equal to, or higher than b.
// Build metadata is ignored, as SemVer §10 requires.
func svCompare(a, b svVersion) int {
	if c := svCmpInt(a.Major, b.Major); c != 0 {
		return c
	}
	if c := svCmpInt(a.Minor, b.Minor); c != 0 {
		return c
	}
	if c := svCmpInt(a.Patch, b.Patch); c != 0 {
		return c
	}
	return svComparePrerelease(a.Prerelease, b.Prerelease)
}

func svCmpInt(a, b int) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

// svComparePrerelease implements SemVer §11: a prerelease ranks below the
// same version without one; numeric identifiers compare numerically and rank
// below alphanumeric ones.
func svComparePrerelease(a, b string) int {
	if a == b {
		return 0
	}
	if a == "" {
		return 1
	}
	if b == "" {
		return -1
	}
	as := strings.Split(a, ".")
	bs := strings.Split(b, ".")
	for i := 0; i < len(as) && i < len(bs); i++ {
		if c := svCompareIdentifier(as[i], bs[i]); c != 0 {
			return c
		}
	}
	return svCmpInt(len(as), len(bs))
}

func svCompareIdentifier(a, b string) int {
	an, aNum := svAsNumber(a)
	bn, bNum := svAsNumber(b)
	if aNum && bNum {
		return svCmpInt(an, bn)
	}
	if aNum {
		return -1
	}
	if bNum {
		return 1
	}
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func svAsNumber(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, false
	}
	return n, true
}

// svBumpPrefix classifies the move a -> b as "major", "minor" or "patch";
// empty string means b is not strictly greater than a.
//
// This is the heart of the ledger: the shipment class is *derived* from the
// two version numbers, so a builder cannot label a breaking change as a patch.
func svBumpPrefix(a, b svVersion) string {
	if svCompare(a, b) >= 0 {
		return ""
	}
	if b.Major != a.Major {
		return "major"
	}
	if b.Minor != a.Minor {
		return "minor"
	}
	return "patch"
}

// ShipLog — an append-only, on-chain release ledger whose classification is
// computed rather than claimed.
//
// A builder records a shipment by supplying the previous version and the new
// one. The realm parses both (SemVer 2.0.0), derives the bump class itself
// ("major"/"minor"/"patch"), and rejects records that do not hold up:
//
//   - a version that does not strictly increase;
//   - a "from" that is not the last version this project actually shipped —
//     which is what makes the ledger a chain of evidence rather than a bag
//     of independent claims;
//   - an author field at all: the writer is the transaction caller, read from
//     the realm context, never a string the submitter can choose.
//
// The realm is deliberately dependency-free: SemVer lives in semver.gno in
// this same package, so no imported package can be re-published underneath it.
package shiplog

import (
	"strconv"
	"strings"
)

// Release is one recorded shipment.
type Release struct {
	Seq         int
	Project     string
	FromVersion string // "" only for the genesis record of a project
	ToVersion   string
	Bump        string // "major" | "minor" | "patch" | "genesis"
	Note        string
	Author      string
}

// Project is one builder's ledger.
type Project struct {
	Slug     string
	Owner    string
	Releases []Release
}

var (
	projects     []*Project
	projectIndex = map[string]*Project{}
	releaseTotal int
)

const (
	maxSlugLen    = 32
	maxNoteLen    = 280
	maxReleases   = 500
	maxProjects   = 200
	renderPerPage = 50
)

// Register opens an empty ledger for slug, owned by the caller.
func Register(cur realm, slug string) {
	caller := cur.Previous().Address().String()
	if err := checkSlug(slug); err != "" {
		panic(err)
	}
	if _, ok := projectIndex[slug]; ok {
		panic("shiplog: project already registered: " + slug)
	}
	if len(projects) >= maxProjects {
		panic("shiplog: project cap reached")
	}
	p := &Project{Slug: slug, Owner: caller}
	projects = append(projects, p)
	projectIndex[slug] = p
}

// Ship appends a release to slug's ledger.
//
// from is "" for the project's first release. The caller must be the project
// owner; the bump class and the chain-of-evidence check are recomputed here.
func Ship(cur realm, slug, from, to, note string) Release {
	caller := cur.Previous().Address().String()
	p, ok := projectIndex[slug]
	if !ok {
		panic("shiplog: unknown project: " + slug)
	}
	if p.Owner != caller {
		panic("shiplog: caller is not the project owner")
	}
	if len(p.Releases) >= maxReleases {
		panic("shiplog: release cap reached")
	}
	if len(note) > maxNoteLen {
		panic("shiplog: note too long")
	}
	if strings.ContainsAny(note, "\r\n") {
		panic("shiplog: note must be a single line")
	}

	toV, err := parseSemver(to)
	if err != nil {
		panic("shiplog: bad version " + strconv.Quote(to) + ": " + err.Error())
	}

	bump := "genesis"
	if from != "" {
		fromV, ferr := parseSemver(from)
		if ferr != nil {
			panic("shiplog: bad previous version " + strconv.Quote(from) + ": " + ferr.Error())
		}
		bump = svBumpPrefix(fromV, toV)
		if bump == "" {
			panic("shiplog: version must increase: " + from + " -> " + to)
		}
	}

	if n := len(p.Releases); n > 0 {
		last := p.Releases[n-1].ToVersion
		if from != last {
			panic("shiplog: from must equal last shipped version (" + last + ")")
		}
	} else if from != "" {
		panic("shiplog: first release must have an empty from")
	}

	r := Release{
		Seq:         len(p.Releases) + 1,
		Project:     slug,
		FromVersion: from,
		ToVersion:   to,
		Bump:        bump,
		Note:        note,
		Author:      caller,
	}
	p.Releases = append(p.Releases, r)
	releaseTotal++
	return r
}

// Count returns how many releases slug has recorded.
func Count(slug string) int {
	if p, ok := projectIndex[slug]; ok {
		return len(p.Releases)
	}
	return 0
}

// Total returns the number of releases and projects recorded.
func Total() (int, int) { return releaseTotal, len(projects) }

// Latest returns the newest release of slug.
func Latest(slug string) (Release, bool) {
	p, ok := projectIndex[slug]
	if !ok || len(p.Releases) == 0 {
		return Release{}, false
	}
	return p.Releases[len(p.Releases)-1], true
}

// BumpClass returns the derived class of the move from -> to, or "" when to
// is not greater. Pure read: no state is touched, so any client can ask the
// same question the realm would answer on a write.
func BumpClass(from, to string) string {
	if from == "" {
		if _, err := parseSemver(to); err != nil {
			return ""
		}
		return "genesis"
	}
	a, err := parseSemver(from)
	if err != nil {
		return ""
	}
	b, err := parseSemver(to)
	if err != nil {
		return ""
	}
	return svBumpPrefix(a, b)
}

// Valid reports whether s is a SemVer 2.0.0 string.
func Valid(s string) bool {
	_, err := parseSemver(s)
	return err == nil
}

func checkSlug(s string) string {
	if s == "" {
		return "shiplog: empty project slug"
	}
	if len(s) > maxSlugLen {
		return "shiplog: project slug too long"
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_'
		if !ok {
			return "shiplog: project slug may only contain a-z 0-9 - _"
		}
	}
	return ""
}

func bumpTag(b string) string {
	switch b {
	case "major":
		return "BREAKING"
	case "minor":
		return "FEATURE"
	case "patch":
		return "FIX"
	case "genesis":
		return "GENESIS"
	}
	return strings.ToUpper(b)
}

func shortAddr(a string) string {
	if len(a) <= 12 {
		return a
	}
	return a[:8] + "…" + a[len(a)-4:]
}

// Render draws the ledger as markdown. path selects a single project when set.
func Render(path string) string {
	var b strings.Builder
	total, nproj := Total()
	b.WriteString("# ShipLog\n\n")
	b.WriteString("An append-only release ledger where **the shipment class is computed, " +
		"not claimed**: the realm derives `major`/`minor`/`patch` from the two " +
		"SemVer 2.0.0 versions it is given, and rejects any record whose `from` " +
		"is not the version this project actually shipped last. The author of " +
		"each row is the calling address, never a self-declared field.\n\n")
	b.WriteString("```\nRegister(cur realm, slug string)\n")
	b.WriteString("Ship(cur realm, slug, from, to, note string) Release\n")
	b.WriteString("Count(slug string) int      Total() (int, int)\n")
	b.WriteString("Latest(slug string) (Release, bool)    BumpClass(from, to string) string\n```\n\n")
	b.WriteString("- projects: **" + strconv.Itoa(nproj) + "**\n")
	b.WriteString("- releases: **" + strconv.Itoa(total) + "**\n")
	b.WriteString("- engine: `semver.gno` in this realm (pure Gno, zero imports beyond stdlib)\n\n")

	if len(projects) == 0 {
		b.WriteString("_No projects registered yet._\n")
		return b.String()
	}

	if path != "" {
		p, ok := projectIndex[path]
		if !ok {
			return b.String() + "\n_Unknown project: " + escapeInline(path) + "_\n"
		}
		writeProject(&b, p)
		return b.String()
	}

	b.WriteString("## Projects\n\n| project | owner | releases | latest |\n|---|---|---|---|\n")
	for _, p := range projects {
		latest := "—"
		if n := len(p.Releases); n > 0 {
			latest = "`" + p.Releases[n-1].ToVersion + "`"
		}
		b.WriteString("| [" + p.Slug + "](" + p.Slug + ") | `" + shortAddr(p.Owner) + "` | " +
			strconv.Itoa(len(p.Releases)) + " | " + latest + " |\n")
	}
	b.WriteString("\n")
	for _, p := range projects {
		writeProject(&b, p)
	}
	return b.String()
}

func writeProject(b *strings.Builder, p *Project) {
	b.WriteString("## " + p.Slug + "\n\n")
	b.WriteString("owner: `" + p.Owner + "`\n\n")
	if len(p.Releases) == 0 {
		b.WriteString("_no releases yet_\n\n")
		return
	}
	b.WriteString("| seq | version | bump | note | author |\n|---|---|---|---|---|\n")
	for _, r := range p.Releases {
		note := r.Note
		if note == "" {
			note = "—"
		}
		b.WriteString("| " + strconv.Itoa(r.Seq) + " | `" + r.ToVersion + "` | " +
			bumpTag(r.Bump) + " | " + note + " | `" + shortAddr(r.Author) + "` |\n")
	}
	b.WriteString("\n")
}

// escapeInline neutralises backticks in caller-supplied path text so a crafted
// path cannot break out of the code span it is rendered into.
func escapeInline(s string) string {
	return strings.ReplaceAll(s, "`", "'")
}

package shiplog

import "testing"

func TestParseSemver(t *testing.T) {
	valid := []string{
		"0.0.1", "1.2.3", "10.20.30", "1.0.0-alpha", "1.0.0-alpha.1",
		"1.0.0-0.3.7", "1.0.0-x.7.z.92", "1.0.0+20130313144700",
		"1.0.0-beta+exp.sha.5114f85",
	}
	for _, s := range valid {
		if _, err := parseSemver(s); err != nil {
			t.Fatalf("parseSemver(%q) unexpected error: %v", s, err)
		}
	}
	invalid := []string{
		"", "1", "1.2", "1.2.3.4", "01.2.3", "1.02.3", "1.2.03",
		"1.2.3-", "1.2.3-01", "1.2.3+", "1.2.3-a..b",
		"v1.2.3", "1.2.-3", "1.2.3-alpha_beta", " 1.2.3",
	}
	for _, s := range invalid {
		if Valid(s) {
			t.Fatalf("Valid(%q) = true, want false", s)
		}
	}
}

func TestPrecedenceChain(t *testing.T) {
	// The ordering example from semver.org §11, ascending.
	chain := []string{
		"1.0.0-alpha", "1.0.0-alpha.1", "1.0.0-alpha.beta", "1.0.0-beta",
		"1.0.0-beta.2", "1.0.0-beta.11", "1.0.0-rc.1", "1.0.0",
	}
	for i := 0; i < len(chain)-1; i++ {
		a, err := parseSemver(chain[i])
		if err != nil {
			t.Fatalf("parse %q: %v", chain[i], err)
		}
		b, err := parseSemver(chain[i+1])
		if err != nil {
			t.Fatalf("parse %q: %v", chain[i+1], err)
		}
		if !(svCompare(b, a) > 0) {
			t.Fatalf("expected %q > %q", chain[i+1], chain[i])
		}
		if svCompare(a, b) > 0 {
			t.Fatalf("expected NOT %q > %q", chain[i], chain[i+1])
		}
	}
}

func TestBuildMetadataIgnored(t *testing.T) {
	a, _ := parseSemver("1.0.0+build.1")
	b, _ := parseSemver("1.0.0+build.2")
	if svCompare(a, b) != 0 {
		t.Fatalf("build metadata must not affect precedence")
	}
}

func TestBumpClass(t *testing.T) {
	cases := []struct{ from, to, want string }{
		{"", "0.1.0", "genesis"},
		{"1.0.0", "2.0.0", "major"},
		{"1.0.0", "1.1.0", "minor"},
		{"1.0.0", "1.0.1", "patch"},
		{"1.0.0", "1.0.0", ""},
		{"1.2.0", "1.1.9", ""},
		{"1.0.0-rc.1", "1.0.0", "patch"},
		{"1.0.0", "1.0.0-rc.1", ""},
	}
	for _, c := range cases {
		if got := BumpClass(c.from, c.to); got != c.want {
			t.Fatalf("BumpClass(%q,%q) = %q, want %q", c.from, c.to, got, c.want)
		}
	}
}

// TestLedgerLifecycle drives the state machine end to end: genesis, three
// bumps, then the two rejection paths that make the ledger trustworthy.
func TestLedgerLifecycle(cur realm, t *testing.T) {
	const me = "g1e73sfpdr5ulzcuv6e4wv973de2huhuyhx65rxy"
	testing.SetRealm(testing.NewUserRealm(me))

	Register(cross(cur), "tavern-kit")
	if got := Count("tavern-kit"); got != 0 {
		t.Fatalf("fresh project has %d releases, want 0", got)
	}

	r := Ship(cross(cur), "tavern-kit", "", "0.1.0", "first public cut")
	if r.Bump != "genesis" || r.Seq != 1 {
		t.Fatalf("genesis record = %+v", r)
	}
	if r.Author != me {
		t.Fatalf("author = %q, want caller %q", r.Author, me)
	}

	if r := Ship(cross(cur), "tavern-kit", "0.1.0", "0.2.0", "ledger render"); r.Bump != "minor" {
		t.Fatalf("0.1.0->0.2.0 classified %q", r.Bump)
	}
	if r := Ship(cross(cur), "tavern-kit", "0.2.0", "0.2.1", "escaping fix"); r.Bump != "patch" {
		t.Fatalf("0.2.0->0.2.1 classified %q", r.Bump)
	}
	if r := Ship(cross(cur), "tavern-kit", "0.2.1", "1.0.0", "stable API"); r.Bump != "major" {
		t.Fatalf("0.2.1->1.0.0 classified %q", r.Bump)
	}

	if got := Count("tavern-kit"); got != 4 {
		t.Fatalf("count = %d, want 4", got)
	}
	if got, _ := Total(); got < 4 {
		t.Fatalf("total releases = %d, want >= 4", got)
	}
	last, ok := Latest("tavern-kit")
	if !ok || last.ToVersion != "1.0.0" {
		t.Fatalf("latest = %+v ok=%v", last, ok)
	}
}

// TestRejectsBrokenChain covers the property that makes this a chain rather
// than a bag of claims: `from` must be the version actually shipped last.
func TestRejectsBrokenChain(cur realm, t *testing.T) {
	const me = "g1e73sfpdr5ulzcuv6e4wv973de2huhuyhx65rxy"
	testing.SetRealm(testing.NewUserRealm(me))
	Register(cross(cur), "chain-test")
	Ship(cross(cur), "chain-test", "", "1.0.0", "start")

	if rec := revive(func() { Ship(cross(cur), "chain-test", "0.9.0", "1.0.1", "wrong from") }); rec == nil {
		t.Fatalf("expected panic when from does not match last shipped version")
	}
	if rec := revive(func() { Ship(cross(cur), "chain-test", "1.0.0", "1.0.0", "no increase") }); rec == nil {
		t.Fatalf("expected panic when version does not increase")
	}
	if rec := revive(func() { Ship(cross(cur), "chain-test", "1.0.0", "1.0.0-rc.1", "downgrade") }); rec == nil {
		t.Fatalf("expected panic on downgrade to prerelease")
	}
	if rec := revive(func() { Register(cross(cur), "chain-test") }); rec == nil {
		t.Fatalf("expected panic on duplicate registration")
	}
	if got := Count("chain-test"); got != 1 {
		t.Fatalf("rejected records mutated the ledger: count = %d, want 1", got)
	}
}

// TestOnlyOwnerWrites proves authorship is enforced, not self-declared.
func TestOnlyOwnerWrites(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm("g1e73sfpdr5ulzcuv6e4wv973de2huhuyhx65rxy"))
	Register(cross(cur), "owned-test")
	Ship(cross(cur), "owned-test", "", "0.1.0", "mine")

	testing.SetRealm(testing.NewUserRealm("g1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq"))
	if rec := revive(func() { Ship(cross(cur), "owned-test", "0.1.0", "0.1.1", "not mine") }); rec == nil {
		t.Fatalf("expected panic when a non-owner writes")
	}
}

// TestRenderEscapesPathPerProject covers the injection surface: path text is
// caller-controlled and must not break out of the code span.
func TestRenderEscapesPathPerProject(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm("g1e73sfpdr5ulzcuv6e4wv973de2huhuyhx65rxy"))
	Register(cross(cur), "render-test")
	Ship(cross(cur), "render-test", "", "2.0.0", "ship it")

	out := Render("")
	if !contains(out, "render-test") || !contains(out, "2.0.0") {
		t.Fatalf("render lost the project: %s", out)
	}
	bad := Render("no-such-`project`")
	if contains(bad, "no-such-`project`") {
		t.Fatalf("path backtick was not neutralised: %s", bad)
	}
}

func contains(s, sub string) bool {
	if len(sub) == 0 {
		return true
	}
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

package shiplog

// SemVer 2.0.0 (https://semver.org) parsing and precedence, implemented in
// pure Gno inside this realm so the ledger has no external package dependency
// that could be re-published under it.
//
// Names are prefixed with `sv` because a realm file shares one package
// namespace with shiplog.gno.

import (
	"errors"
	"strconv"
	"strings"
)

// svVersion is a parsed semantic version.
type svVersion struct {
	Major      int
	Minor      int
	Patch      int
	Prerelease string // without the leading '-'; empty when absent
	Build      string // without the leading '+'
}

var (
	errSvEmpty     = errors.New("empty version")
	errSvTooLong   = errors.New("version string too long")
	errSvZero      = errors.New("numeric identifier with leading zero")
	errSvParts     = errors.New("version must be major.minor.patch")
	errSvNegative  = errors.New("negative numeric identifier")
	errSvIdent     = errors.New("invalid identifier character")
	errSvEmptyPart = errors.New("empty dot-separated identifier")
)

const svMaxLen = 128

// parseSemver parses "1.4.2", "0.9.0-rc.1", "2.0.0+build.7" and rejects
// anything SemVer calls invalid — notably a leading zero in a numeric part.
func parseSemver(s string) (svVersion, error) {
	var v svVersion
	if s == "" {
		return v, errSvEmpty
	}
	if len(s) > svMaxLen {
		return v, errSvTooLong
	}

	rest := s
	// Build metadata is split first: it may legitimately contain '-' itself.
	if i := strings.IndexByte(rest, '+'); i >= 0 {
		v.Build = rest[i+1:]
		rest = rest[:i]
		if err := svValidateIdentifiers(v.Build, false); err != nil {
			return svVersion{}, err
		}
	}
	if i := strings.IndexByte(rest, '-'); i >= 0 {
		v.Prerelease = rest[i+1:]
		rest = rest[:i]
		if v.Prerelease == "" {
			return svVersion{}, errSvIdent
		}
		if err := svValidateIdentifiers(v.Prerelease, true); err != nil {
			return svVersion{}, err
		}
	}

	parts := strings.Split(rest, ".")
	if len(parts) != 3 {
		return svVersion{}, errSvParts
	}
	nums := [3]int{}
	for i := 0; i < 3; i++ {
		n, err := svParseNumeric(parts[i])
		if err != nil {
			return svVersion{}, err
		}
		nums[i] = n
	}
	v.Major, v.Minor, v.Patch = nums[0], nums[1], nums[2]
	return v, nil
}

func svParseNumeric(s string) (int, error) {
	if s == "" {
		return 0, errSvEmptyPart
	}
	if len(s) > 1 && s[0] == '0' {
		return 0, errSvZero
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			if s[i] == '-' {
				return 0, errSvNegative
			}
			return 0, errSvIdent
		}
	}
	n, err := strconv.Atoi(s)
	if err != nil || n < 0 {
		return 0, errSvNegative
	}
	return n, nil
}

func svValidateIdentifiers(s string, noLeadingZero bool) error {
	if s == "" {
		return errSvIdent
	}
	for _, id := range strings.Split(s, ".") {
		if id == "" {
			return errSvEmptyPart
		}
		numeric := true
		for i := 0; i < len(id); i++ {
			c := id[i]
			if !svIsAlnumHyphen(c) {
				return errSvIdent
			}
			if c < '0' || c > '9' {
				numeric = false
			}
		}
		if noLeadingZero && numeric && len(id) > 1 && id[0] == '0' {
			return errSvZero
		}
	}
	return nil
}

func svIsAlnumHyphen(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '-'
}

// String renders the version back in canonical form.
func (v svVersion) String() string {
	s := strconv.Itoa(v.Major) + "." + strconv.Itoa(v.Minor) + "." + strconv.Itoa(v.Patch)
	if v.Prerelease != "" {
		s += "-" + v.Prerelease
	}
	if v.Build != "" {
		s += "+" + v.Build
	}
	return s
}

// svCompare returns -1, 0 or +1 as a is lower than, equal to, or higher than b.
// Build metadata is ignored, as SemVer §10 requires.
func svCompare(a, b svVersion) int {
	if c := svCmpInt(a.Major, b.Major); c != 0 {
		return c
	}
	if c := svCmpInt(a.Minor, b.Minor); c != 0 {
		return c
	}
	if c := svCmpInt(a.Patch, b.Patch); c != 0 {
		return c
	}
	return svComparePrerelease(a.Prerelease, b.Prerelease)
}

func svCmpInt(a, b int) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

// svComparePrerelease implements SemVer §11: a prerelease ranks below the
// same version without one; numeric identifiers compare numerically and rank
// below alphanumeric ones.
func svComparePrerelease(a, b string) int {
	if a == b {
		return 0
	}
	if a == "" {
		return 1
	}
	if b == "" {
		return -1
	}
	as := strings.Split(a, ".")
	bs := strings.Split(b, ".")
	for i := 0; i < len(as) && i < len(bs); i++ {
		if c := svCompareIdentifier(as[i], bs[i]); c != 0 {
			return c
		}
	}
	return svCmpInt(len(as), len(bs))
}

func svCompareIdentifier(a, b string) int {
	an, aNum := svAsNumber(a)
	bn, bNum := svAsNumber(b)
	if aNum && bNum {
		return svCmpInt(an, bn)
	}
	if aNum {
		return -1
	}
	if bNum {
		return 1
	}
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func svAsNumber(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, false
	}
	return n, true
}

// svBumpPrefix classifies the move a -> b as "major", "minor" or "patch";
// empty string means b is not strictly greater than a.
//
// This is the heart of the ledger: the shipment class is *derived* from the
// two version numbers, so a builder cannot label a breaking change as a patch.
func svBumpPrefix(a, b svVersion) string {
	if svCompare(a, b) >= 0 {
		return ""
	}
	if b.Major != a.Major {
		return "major"
	}
	if b.Minor != a.Minor {
		return "minor"
	}
	return "patch"
}

// ShipLog — an append-only, on-chain release ledger whose classification is
// computed rather than claimed.
//
// A builder records a shipment by supplying the previous version and the new
// one. The realm parses both (SemVer 2.0.0), derives the bump class itself
// ("major"/"minor"/"patch"), and rejects records that do not hold up:
//
//   - a version that does not strictly increase;
//   - a "from" that is not the last version this project actually shipped —
//     which is what makes the ledger a chain of evidence rather than a bag
//     of independent claims;
//   - an author field at all: the writer is the transaction caller, read from
//     the realm context, never a string the submitter can choose.
//
// The realm is deliberately dependency-free: SemVer lives in semver.gno in
// this same package, so no imported package can be re-published underneath it.
package shiplog

import (
	"strconv"
	"strings"
)

// Release is one recorded shipment.
type Release struct {
	Seq         int
	Project     string
	FromVersion string // "" only for the genesis record of a project
	ToVersion   string
	Bump        string // "major" | "minor" | "patch" | "genesis"
	Note        string
	Author      string
}

// Project is one builder's ledger.
type Project struct {
	Slug     string
	Owner    string
	Releases []Release
}

var (
	projects     []*Project
	projectIndex = map[string]*Project{}
	releaseTotal int
)

const (
	maxSlugLen    = 32
	maxNoteLen    = 280
	maxReleases   = 500
	maxProjects   = 200
	renderPerPage = 50
)

// Register opens an empty ledger for slug, owned by the caller.
func Register(cur realm, slug string) {
	caller := cur.Previous().Address().String()
	if err := checkSlug(slug); err != "" {
		panic(err)
	}
	if _, ok := projectIndex[slug]; ok {
		panic("shiplog: project already registered: " + slug)
	}
	if len(projects) >= maxProjects {
		panic("shiplog: project cap reached")
	}
	p := &Project{Slug: slug, Owner: caller}
	projects = append(projects, p)
	projectIndex[slug] = p
}

// Ship appends a release to slug's ledger.
//
// from is "" for the project's first release. The caller must be the project
// owner; the bump class and the chain-of-evidence check are recomputed here.
func Ship(cur realm, slug, from, to, note string) Release {
	caller := cur.Previous().Address().String()
	p, ok := projectIndex[slug]
	if !ok {
		panic("shiplog: unknown project: " + slug)
	}
	if p.Owner != caller {
		panic("shiplog: caller is not the project owner")
	}
	if len(p.Releases) >= maxReleases {
		panic("shiplog: release cap reached")
	}
	if len(note) > maxNoteLen {
		panic("shiplog: note too long")
	}
	if strings.ContainsAny(note, "\r\n") {
		panic("shiplog: note must be a single line")
	}

	toV, err := parseSemver(to)
	if err != nil {
		panic("shiplog: bad version " + strconv.Quote(to) + ": " + err.Error())
	}

	bump := "genesis"
	if from != "" {
		fromV, ferr := parseSemver(from)
		if ferr != nil {
			panic("shiplog: bad previous version " + strconv.Quote(from) + ": " + ferr.Error())
		}
		bump = svBumpPrefix(fromV, toV)
		if bump == "" {
			panic("shiplog: version must increase: " + from + " -> " + to)
		}
	}

	if n := len(p.Releases); n > 0 {
		last := p.Releases[n-1].ToVersion
		if from != last {
			panic("shiplog: from must equal last shipped version (" + last + ")")
		}
	} else if from != "" {
		panic("shiplog: first release must have an empty from")
	}

	r := Release{
		Seq:         len(p.Releases) + 1,
		Project:     slug,
		FromVersion: from,
		ToVersion:   to,
		Bump:        bump,
		Note:        note,
		Author:      caller,
	}
	p.Releases = append(p.Releases, r)
	releaseTotal++
	return r
}

// Count returns how many releases slug has recorded.
func Count(slug string) int {
	if p, ok := projectIndex[slug]; ok {
		return len(p.Releases)
	}
	return 0
}

// Total returns the number of releases and projects recorded.
func Total() (int, int) { return releaseTotal, len(projects) }

// Latest returns the newest release of slug.
func Latest(slug string) (Release, bool) {
	p, ok := projectIndex[slug]
	if !ok || len(p.Releases) == 0 {
		return Release{}, false
	}
	return p.Releases[len(p.Releases)-1], true
}

// BumpClass returns the derived class of the move from -> to, or "" when to
// is not greater. Pure read: no state is touched, so any client can ask the
// same question the realm would answer on a write.
func BumpClass(from, to string) string {
	if from == "" {
		if _, err := parseSemver(to); err != nil {
			return ""
		}
		return "genesis"
	}
	a, err := parseSemver(from)
	if err != nil {
		return ""
	}
	b, err := parseSemver(to)
	if err != nil {
		return ""
	}
	return svBumpPrefix(a, b)
}

// Valid reports whether s is a SemVer 2.0.0 string.
func Valid(s string) bool {
	_, err := parseSemver(s)
	return err == nil
}

func checkSlug(s string) string {
	if s == "" {
		return "shiplog: empty project slug"
	}
	if len(s) > maxSlugLen {
		return "shiplog: project slug too long"
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_'
		if !ok {
			return "shiplog: project slug may only contain a-z 0-9 - _"
		}
	}
	return ""
}

func bumpTag(b string) string {
	switch b {
	case "major":
		return "BREAKING"
	case "minor":
		return "FEATURE"
	case "patch":
		return "FIX"
	case "genesis":
		return "GENESIS"
	}
	return strings.ToUpper(b)
}

func shortAddr(a string) string {
	if len(a) <= 12 {
		return a
	}
	return a[:8] + "…" + a[len(a)-4:]
}

// Render draws the ledger as markdown. path selects a single project when set.
func Render(path string) string {
	var b strings.Builder
	total, nproj := Total()
	b.WriteString("# ShipLog\n\n")
	b.WriteString("An append-only release ledger where **the shipment class is computed, " +
		"not claimed**: the realm derives `major`/`minor`/`patch` from the two " +
		"SemVer 2.0.0 versions it is given, and rejects any record whose `from` " +
		"is not the version this project actually shipped last. The author of " +
		"each row is the calling address, never a self-declared field.\n\n")
	b.WriteString("```\nRegister(cur realm, slug string)\n")
	b.WriteString("Ship(cur realm, slug, from, to, note string) Release\n")
	b.WriteString("Count(slug string) int      Total() (int, int)\n")
	b.WriteString("Latest(slug string) (Release, bool)    BumpClass(from, to string) string\n```\n\n")
	b.WriteString("- projects: **" + strconv.Itoa(nproj) + "**\n")
	b.WriteString("- releases: **" + strconv.Itoa(total) + "**\n")
	b.WriteString("- engine: `semver.gno` in this realm (pure Gno, zero imports beyond stdlib)\n\n")

	if len(projects) == 0 {
		b.WriteString("_No projects registered yet._\n")
		return b.String()
	}

	if path != "" {
		p, ok := projectIndex[path]
		if !ok {
			return b.String() + "\n_Unknown project: " + escapeInline(path) + "_\n"
		}
		writeProject(&b, p)
		return b.String()
	}

	b.WriteString("## Projects\n\n| project | owner | releases | latest |\n|---|---|---|---|\n")
	for _, p := range projects {
		latest := "—"
		if n := len(p.Releases); n > 0 {
			latest = "`" + p.Releases[n-1].ToVersion + "`"
		}
		b.WriteString("| [" + p.Slug + "](" + p.Slug + ") | `" + shortAddr(p.Owner) + "` | " +
			strconv.Itoa(len(p.Releases)) + " | " + latest + " |\n")
	}
	b.WriteString("\n")
	for _, p := range projects {
		writeProject(&b, p)
	}
	return b.String()
}

func writeProject(b *strings.Builder, p *Project) {
	b.WriteString("## " + p.Slug + "\n\n")
	b.WriteString("owner: `" + p.Owner + "`\n\n")
	if len(p.Releases) == 0 {
		b.WriteString("_no releases yet_\n\n")
		return
	}
	b.WriteString("| seq | version | bump | note | author |\n|---|---|---|---|---|\n")
	for _, r := range p.Releases {
		note := r.Note
		if note == "" {
			note = "—"
		}
		b.WriteString("| " + strconv.Itoa(r.Seq) + " | `" + r.ToVersion + "` | " +
			bumpTag(r.Bump) + " | " + note + " | `" + shortAddr(r.Author) + "` |\n")
	}
	b.WriteString("\n")
}

// escapeInline neutralises backticks in caller-supplied path text so a crafted
// path cannot break out of the code span it is rendered into.
func escapeInline(s string) string {
	return strings.ReplaceAll(s, "`", "'")
}

package shiplog

import "testing"

func TestParseSemver(t *testing.T) {
	valid := []string{
		"0.0.1", "1.2.3", "10.20.30", "1.0.0-alpha", "1.0.0-alpha.1",
		"1.0.0-0.3.7", "1.0.0-x.7.z.92", "1.0.0+20130313144700",
		"1.0.0-beta+exp.sha.5114f85",
	}
	for _, s := range valid {
		if _, err := parseSemver(s); err != nil {
			t.Fatalf("parseSemver(%q) unexpected error: %v", s, err)
		}
	}
	invalid := []string{
		"", "1", "1.2", "1.2.3.4", "01.2.3", "1.02.3", "1.2.03",
		"1.2.3-", "1.2.3-01", "1.2.3+", "1.2.3-a..b",
		"v1.2.3", "1.2.-3", "1.2.3-alpha_beta", " 1.2.3",
	}
	for _, s := range invalid {
		if Valid(s) {
			t.Fatalf("Valid(%q) = true, want false", s)
		}
	}
}

func TestPrecedenceChain(t *testing.T) {
	// The ordering example from semver.org §11, ascending.
	chain := []string{
		"1.0.0-alpha", "1.0.0-alpha.1", "1.0.0-alpha.beta", "1.0.0-beta",
		"1.0.0-beta.2", "1.0.0-beta.11", "1.0.0-rc.1", "1.0.0",
	}
	for i := 0; i < len(chain)-1; i++ {
		a, err := parseSemver(chain[i])
		if err != nil {
			t.Fatalf("parse %q: %v", chain[i], err)
		}
		b, err := parseSemver(chain[i+1])
		if err != nil {
			t.Fatalf("parse %q: %v", chain[i+1], err)
		}
		if !(svCompare(b, a) > 0) {
			t.Fatalf("expected %q > %q", chain[i+1], chain[i])
		}
		if svCompare(a, b) > 0 {
			t.Fatalf("expected NOT %q > %q", chain[i], chain[i+1])
		}
	}
}

func TestBuildMetadataIgnored(t *testing.T) {
	a, _ := parseSemver("1.0.0+build.1")
	b, _ := parseSemver("1.0.0+build.2")
	if svCompare(a, b) != 0 {
		t.Fatalf("build metadata must not affect precedence")
	}
}

func TestBumpClass(t *testing.T) {
	cases := []struct{ from, to, want string }{
		{"", "0.1.0", "genesis"},
		{"1.0.0", "2.0.0", "major"},
		{"1.0.0", "1.1.0", "minor"},
		{"1.0.0", "1.0.1", "patch"},
		{"1.0.0", "1.0.0", ""},
		{"1.2.0", "1.1.9", ""},
		{"1.0.0-rc.1", "1.0.0", "patch"},
		{"1.0.0", "1.0.0-rc.1", ""},
	}
	for _, c := range cases {
		if got := BumpClass(c.from, c.to); got != c.want {
			t.Fatalf("BumpClass(%q,%q) = %q, want %q", c.from, c.to, got, c.want)
		}
	}
}

// TestLedgerLifecycle drives the state machine end to end: genesis, three
// bumps, then the two rejection paths that make the ledger trustworthy.
func TestLedgerLifecycle(cur realm, t *testing.T) {
	const me = "g1e73sfpdr5ulzcuv6e4wv973de2huhuyhx65rxy"
	testing.SetRealm(testing.NewUserRealm(me))

	Register(cross(cur), "tavern-kit")
	if got := Count("tavern-kit"); got != 0 {
		t.Fatalf("fresh project has %d releases, want 0", got)
	}

	r := Ship(cross(cur), "tavern-kit", "", "0.1.0", "first public cut")
	if r.Bump != "genesis" || r.Seq != 1 {
		t.Fatalf("genesis record = %+v", r)
	}
	if r.Author != me {
		t.Fatalf("author = %q, want caller %q", r.Author, me)
	}

	if r := Ship(cross(cur), "tavern-kit", "0.1.0", "0.2.0", "ledger render"); r.Bump != "minor" {
		t.Fatalf("0.1.0->0.2.0 classified %q", r.Bump)
	}
	if r := Ship(cross(cur), "tavern-kit", "0.2.0", "0.2.1", "escaping fix"); r.Bump != "patch" {
		t.Fatalf("0.2.0->0.2.1 classified %q", r.Bump)
	}
	if r := Ship(cross(cur), "tavern-kit", "0.2.1", "1.0.0", "stable API"); r.Bump != "major" {
		t.Fatalf("0.2.1->1.0.0 classified %q", r.Bump)
	}

	if got := Count("tavern-kit"); got != 4 {
		t.Fatalf("count = %d, want 4", got)
	}
	if got, _ := Total(); got < 4 {
		t.Fatalf("total releases = %d, want >= 4", got)
	}
	last, ok := Latest("tavern-kit")
	if !ok || last.ToVersion != "1.0.0" {
		t.Fatalf("latest = %+v ok=%v", last, ok)
	}
}

// TestRejectsBrokenChain covers the property that makes this a chain rather
// than a bag of claims: `from` must be the version actually shipped last.
func TestRejectsBrokenChain(cur realm, t *testing.T) {
	const me = "g1e73sfpdr5ulzcuv6e4wv973de2huhuyhx65rxy"
	testing.SetRealm(testing.NewUserRealm(me))
	Register(cross(cur), "chain-test")
	Ship(cross(cur), "chain-test", "", "1.0.0", "start")

	if rec := revive(func() { Ship(cross(cur), "chain-test", "0.9.0", "1.0.1", "wrong from") }); rec == nil {
		t.Fatalf("expected panic when from does not match last shipped version")
	}
	if rec := revive(func() { Ship(cross(cur), "chain-test", "1.0.0", "1.0.0", "no increase") }); rec == nil {
		t.Fatalf("expected panic when version does not increase")
	}
	if rec := revive(func() { Ship(cross(cur), "chain-test", "1.0.0", "1.0.0-rc.1", "downgrade") }); rec == nil {
		t.Fatalf("expected panic on downgrade to prerelease")
	}
	if rec := revive(func() { Register(cross(cur), "chain-test") }); rec == nil {
		t.Fatalf("expected panic on duplicate registration")
	}
	if got := Count("chain-test"); got != 1 {
		t.Fatalf("rejected records mutated the ledger: count = %d, want 1", got)
	}
}

// TestOnlyOwnerWrites proves authorship is enforced, not self-declared.
func TestOnlyOwnerWrites(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm("g1e73sfpdr5ulzcuv6e4wv973de2huhuyhx65rxy"))
	Register(cross(cur), "owned-test")
	Ship(cross(cur), "owned-test", "", "0.1.0", "mine")

	testing.SetRealm(testing.NewUserRealm("g1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq"))
	if rec := revive(func() { Ship(cross(cur), "owned-test", "0.1.0", "0.1.1", "not mine") }); rec == nil {
		t.Fatalf("expected panic when a non-owner writes")
	}
}

// TestRenderEscapesPathPerProject covers the injection surface: path text is
// caller-controlled and must not break out of the code span.
func TestRenderEscapesPathPerProject(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm("g1e73sfpdr5ulzcuv6e4wv973de2huhuyhx65rxy"))
	Register(cross(cur), "render-test")
	Ship(cross(cur), "render-test", "", "2.0.0", "ship it")

	out := Render("")
	if !contains(out, "render-test") || !contains(out, "2.0.0") {
		t.Fatalf("render lost the project: %s", out)
	}
	bad := Render("no-such-`project`")
	if contains(bad, "no-such-`project`") {
		t.Fatalf("path backtick was not neutralised: %s", bad)
	}
}

func contains(s, sub string) bool {
	if len(sub) == 0 {
		return true
	}
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

package shiplog

// SemVer 2.0.0 (https://semver.org) parsing and precedence, implemented in
// pure Gno inside this realm so the ledger has no external package dependency
// that could be re-published under it.
//
// Names are prefixed with `sv` because a realm file shares one package
// namespace with shiplog.gno.

import (
	"errors"
	"strconv"
	"strings"
)

// svVersion is a parsed semantic version.
type svVersion struct {
	Major      int
	Minor      int
	Patch      int
	Prerelease string // without the leading '-'; empty when absent
	Build      string // without the leading '+'
}

var (
	errSvEmpty     = errors.New("empty version")
	errSvTooLong   = errors.New("version string too long")
	errSvZero      = errors.New("numeric identifier with leading zero")
	errSvParts     = errors.New("version must be major.minor.patch")
	errSvNegative  = errors.New("negative numeric identifier")
	errSvIdent     = errors.New("invalid identifier character")
	errSvEmptyPart = errors.New("empty dot-separated identifier")
)

const svMaxLen = 128

// parseSemver parses "1.4.2", "0.9.0-rc.1", "2.0.0+build.7" and rejects
// anything SemVer calls invalid — notably a leading zero in a numeric part.
func parseSemver(s string) (svVersion, error) {
	var v svVersion
	if s == "" {
		return v, errSvEmpty
	}
	if len(s) > svMaxLen {
		return v, errSvTooLong
	}

	rest := s
	// Build metadata is split first: it may legitimately contain '-' itself.
	if i := strings.IndexByte(rest, '+'); i >= 0 {
		v.Build = rest[i+1:]
		rest = rest[:i]
		if err := svValidateIdentifiers(v.Build, false); err != nil {
			return svVersion{}, err
		}
	}
	if i := strings.IndexByte(rest, '-'); i >= 0 {
		v.Prerelease = rest[i+1:]
		rest = rest[:i]
		if v.Prerelease == "" {
			return svVersion{}, errSvIdent
		}
		if err := svValidateIdentifiers(v.Prerelease, true); err != nil {
			return svVersion{}, err
		}
	}

	parts := strings.Split(rest, ".")
	if len(parts) != 3 {
		return svVersion{}, errSvParts
	}
	nums := [3]int{}
	for i := 0; i < 3; i++ {
		n, err := svParseNumeric(parts[i])
		if err != nil {
			return svVersion{}, err
		}
		nums[i] = n
	}
	v.Major, v.Minor, v.Patch = nums[0], nums[1], nums[2]
	return v, nil
}

func svParseNumeric(s string) (int, error) {
	if s == "" {
		return 0, errSvEmptyPart
	}
	if len(s) > 1 && s[0] == '0' {
		return 0, errSvZero
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			if s[i] == '-' {
				return 0, errSvNegative
			}
			return 0, errSvIdent
		}
	}
	n, err := strconv.Atoi(s)
	if err != nil || n < 0 {
		return 0, errSvNegative
	}
	return n, nil
}

func svValidateIdentifiers(s string, noLeadingZero bool) error {
	if s == "" {
		return errSvIdent
	}
	for _, id := range strings.Split(s, ".") {
		if id == "" {
			return errSvEmptyPart
		}
		numeric := true
		for i := 0; i < len(id); i++ {
			c := id[i]
			if !svIsAlnumHyphen(c) {
				return errSvIdent
			}
			if c < '0' || c > '9' {
				numeric = false
			}
		}
		if noLeadingZero && numeric && len(id) > 1 && id[0] == '0' {
			return errSvZero
		}
	}
	return nil
}

func svIsAlnumHyphen(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '-'
}

// String renders the version back in canonical form.
func (v svVersion) String() string {
	s := strconv.Itoa(v.Major) + "." + strconv.Itoa(v.Minor) + "." + strconv.Itoa(v.Patch)
	if v.Prerelease != "" {
		s += "-" + v.Prerelease
	}
	if v.Build != "" {
		s += "+" + v.Build
	}
	return s
}

// svCompare returns -1, 0 or +1 as a is lower than, equal to, or higher than b.
// Build metadata is ignored, as SemVer §10 requires.
func svCompare(a, b svVersion) int {
	if c := svCmpInt(a.Major, b.Major); c != 0 {
		return c
	}
	if c := svCmpInt(a.Minor, b.Minor); c != 0 {
		return c
	}
	if c := svCmpInt(a.Patch, b.Patch); c != 0 {
		return c
	}
	return svComparePrerelease(a.Prerelease, b.Prerelease)
}

func svCmpInt(a, b int) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

// svComparePrerelease implements SemVer §11: a prerelease ranks below the
// same version without one; numeric identifiers compare numerically and rank
// below alphanumeric ones.
func svComparePrerelease(a, b string) int {
	if a == b {
		return 0
	}
	if a == "" {
		return 1
	}
	if b == "" {
		return -1
	}
	as := strings.Split(a, ".")
	bs := strings.Split(b, ".")
	for i := 0; i < len(as) && i < len(bs); i++ {
		if c := svCompareIdentifier(as[i], bs[i]); c != 0 {
			return c
		}
	}
	return svCmpInt(len(as), len(bs))
}

func svCompareIdentifier(a, b string) int {
	an, aNum := svAsNumber(a)
	bn, bNum := svAsNumber(b)
	if aNum && bNum {
		return svCmpInt(an, bn)
	}
	if aNum {
		return -1
	}
	if bNum {
		return 1
	}
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func svAsNumber(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, false
	}
	return n, true
}

// svBumpPrefix classifies the move a -> b as "major", "minor" or "patch";
// empty string means b is not strictly greater than a.
//
// This is the heart of the ledger: the shipment class is *derived* from the
// two version numbers, so a builder cannot label a breaking change as a patch.
func svBumpPrefix(a, b svVersion) string {
	if svCompare(a, b) >= 0 {
		return ""
	}
	if b.Major != a.Major {
		return "major"
	}
	if b.Minor != a.Minor {
		return "minor"
	}
	return "patch"
}

// ShipLog — an append-only, on-chain release ledger whose classification is
// computed rather than claimed.
//
// A builder records a shipment by supplying the previous version and the new
// one. The realm parses both (SemVer 2.0.0), derives the bump class itself
// ("major"/"minor"/"patch"), and rejects records that do not hold up:
//
//   - a version that does not strictly increase;
//   - a "from" that is not the last version this project actually shipped —
//     which is what makes the ledger a chain of evidence rather than a bag
//     of independent claims;
//   - an author field at all: the writer is the transaction caller, read from
//     the realm context, never a string the submitter can choose.
//
// The realm is deliberately dependency-free: SemVer lives in semver.gno in
// this same package, so no imported package can be re-published underneath it.
package shiplog

import (
	"strconv"
	"strings"
)

// Release is one recorded shipment.
type Release struct {
	Seq         int
	Project     string
	FromVersion string // "" only for the genesis record of a project
	ToVersion   string
	Bump        string // "major" | "minor" | "patch" | "genesis"
	Note        string
	Author      string
}

// Project is one builder's ledger.
type Project struct {
	Slug     string
	Owner    string
	Releases []Release
}

var (
	projects     []*Project
	projectIndex = map[string]*Project{}
	releaseTotal int
)

const (
	maxSlugLen    = 32
	maxNoteLen    = 280
	maxReleases   = 500
	maxProjects   = 200
	renderPerPage = 50
)

// Register opens an empty ledger for slug, owned by the caller.
func Register(cur realm, slug string) {
	caller := cur.Previous().Address().String()
	if err := checkSlug(slug); err != "" {
		panic(err)
	}
	if _, ok := projectIndex[slug]; ok {
		panic("shiplog: project already registered: " + slug)
	}
	if len(projects) >= maxProjects {
		panic("shiplog: project cap reached")
	}
	p := &Project{Slug: slug, Owner: caller}
	projects = append(projects, p)
	projectIndex[slug] = p
}

// Ship appends a release to slug's ledger.
//
// from is "" for the project's first release. The caller must be the project
// owner; the bump class and the chain-of-evidence check are recomputed here.
func Ship(cur realm, slug, from, to, note string) Release {
	caller := cur.Previous().Address().String()
	p, ok := projectIndex[slug]
	if !ok {
		panic("shiplog: unknown project: " + slug)
	}
	if p.Owner != caller {
		panic("shiplog: caller is not the project owner")
	}
	if len(p.Releases) >= maxReleases {
		panic("shiplog: release cap reached")
	}
	if len(note) > maxNoteLen {
		panic("shiplog: note too long")
	}
	if strings.ContainsAny(note, "\r\n") {
		panic("shiplog: note must be a single line")
	}

	toV, err := parseSemver(to)
	if err != nil {
		panic("shiplog: bad version " + strconv.Quote(to) + ": " + err.Error())
	}

	bump := "genesis"
	if from != "" {
		fromV, ferr := parseSemver(from)
		if ferr != nil {
			panic("shiplog: bad previous version " + strconv.Quote(from) + ": " + ferr.Error())
		}
		bump = svBumpPrefix(fromV, toV)
		if bump == "" {
			panic("shiplog: version must increase: " + from + " -> " + to)
		}
	}

	if n := len(p.Releases); n > 0 {
		last := p.Releases[n-1].ToVersion
		if from != last {
			panic("shiplog: from must equal last shipped version (" + last + ")")
		}
	} else if from != "" {
		panic("shiplog: first release must have an empty from")
	}

	r := Release{
		Seq:         len(p.Releases) + 1,
		Project:     slug,
		FromVersion: from,
		ToVersion:   to,
		Bump:        bump,
		Note:        note,
		Author:      caller,
	}
	p.Releases = append(p.Releases, r)
	releaseTotal++
	return r
}

// Count returns how many releases slug has recorded.
func Count(slug string) int {
	if p, ok := projectIndex[slug]; ok {
		return len(p.Releases)
	}
	return 0
}

// Total returns the number of releases and projects recorded.
func Total() (int, int) { return releaseTotal, len(projects) }

// Latest returns the newest release of slug.
func Latest(slug string) (Release, bool) {
	p, ok := projectIndex[slug]
	if !ok || len(p.Releases) == 0 {
		return Release{}, false
	}
	return p.Releases[len(p.Releases)-1], true
}

// BumpClass returns the derived class of the move from -> to, or "" when to
// is not greater. Pure read: no state is touched, so any client can ask the
// same question the realm would answer on a write.
func BumpClass(from, to string) string {
	if from == "" {
		if _, err := parseSemver(to); err != nil {
			return ""
		}
		return "genesis"
	}
	a, err := parseSemver(from)
	if err != nil {
		return ""
	}
	b, err := parseSemver(to)
	if err != nil {
		return ""
	}
	return svBumpPrefix(a, b)
}

// Valid reports whether s is a SemVer 2.0.0 string.
func Valid(s string) bool {
	_, err := parseSemver(s)
	return err == nil
}

func checkSlug(s string) string {
	if s == "" {
		return "shiplog: empty project slug"
	}
	if len(s) > maxSlugLen {
		return "shiplog: project slug too long"
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_'
		if !ok {
			return "shiplog: project slug may only contain a-z 0-9 - _"
		}
	}
	return ""
}

func bumpTag(b string) string {
	switch b {
	case "major":
		return "BREAKING"
	case "minor":
		return "FEATURE"
	case "patch":
		return "FIX"
	case "genesis":
		return "GENESIS"
	}
	return strings.ToUpper(b)
}

func shortAddr(a string) string {
	if len(a) <= 12 {
		return a
	}
	return a[:8] + "…" + a[len(a)-4:]
}

// Render draws the ledger as markdown. path selects a single project when set.
func Render(path string) string {
	var b strings.Builder
	total, nproj := Total()
	b.WriteString("# ShipLog\n\n")
	b.WriteString("An append-only release ledger where **the shipment class is computed, " +
		"not claimed**: the realm derives `major`/`minor`/`patch` from the two " +
		"SemVer 2.0.0 versions it is given, and rejects any record whose `from` " +
		"is not the version this project actually shipped last. The author of " +
		"each row is the calling address, never a self-declared field.\n\n")
	b.WriteString("```\nRegister(cur realm, slug string)\n")
	b.WriteString("Ship(cur realm, slug, from, to, note string) Release\n")
	b.WriteString("Count(slug string) int      Total() (int, int)\n")
	b.WriteString("Latest(slug string) (Release, bool)    BumpClass(from, to string) string\n```\n\n")
	b.WriteString("- projects: **" + strconv.Itoa(nproj) + "**\n")
	b.WriteString("- releases: **" + strconv.Itoa(total) + "**\n")
	b.WriteString("- engine: `semver.gno` in this realm (pure Gno, zero imports beyond stdlib)\n\n")

	if len(projects) == 0 {
		b.WriteString("_No projects registered yet._\n")
		return b.String()
	}

	if path != "" {
		p, ok := projectIndex[path]
		if !ok {
			return b.String() + "\n_Unknown project: " + escapeInline(path) + "_\n"
		}
		writeProject(&b, p)
		return b.String()
	}

	b.WriteString("## Projects\n\n| project | owner | releases | latest |\n|---|---|---|---|\n")
	for _, p := range projects {
		latest := "—"
		if n := len(p.Releases); n > 0 {
			latest = "`" + p.Releases[n-1].ToVersion + "`"
		}
		b.WriteString("| [" + p.Slug + "](" + p.Slug + ") | `" + shortAddr(p.Owner) + "` | " +
			strconv.Itoa(len(p.Releases)) + " | " + latest + " |\n")
	}
	b.WriteString("\n")
	for _, p := range projects {
		writeProject(&b, p)
	}
	return b.String()
}

func writeProject(b *strings.Builder, p *Project) {
	b.WriteString("## " + p.Slug + "\n\n")
	b.WriteString("owner: `" + p.Owner + "`\n\n")
	if len(p.Releases) == 0 {
		b.WriteString("_no releases yet_\n\n")
		return
	}
	b.WriteString("| seq | version | bump | note | author |\n|---|---|---|---|---|\n")
	for _, r := range p.Releases {
		note := r.Note
		if note == "" {
			note = "—"
		}
		b.WriteString("| " + strconv.Itoa(r.Seq) + " | `" + r.ToVersion + "` | " +
			bumpTag(r.Bump) + " | " + note + " | `" + shortAddr(r.Author) + "` |\n")
	}
	b.WriteString("\n")
}

// escapeInline neutralises backticks in caller-supplied path text so a crafted
// path cannot break out of the code span it is rendered into.
func escapeInline(s string) string {
	return strings.ReplaceAll(s, "`", "'")
}

package shiplog

import "testing"

func TestParseSemver(t *testing.T) {
	valid := []string{
		"0.0.1", "1.2.3", "10.20.30", "1.0.0-alpha", "1.0.0-alpha.1",
		"1.0.0-0.3.7", "1.0.0-x.7.z.92", "1.0.0+20130313144700",
		"1.0.0-beta+exp.sha.5114f85",
	}
	for _, s := range valid {
		if _, err := parseSemver(s); err != nil {
			t.Fatalf("parseSemver(%q) unexpected error: %v", s, err)
		}
	}
	invalid := []string{
		"", "1", "1.2", "1.2.3.4", "01.2.3", "1.02.3", "1.2.03",
		"1.2.3-", "1.2.3-01", "1.2.3+", "1.2.3-a..b",
		"v1.2.3", "1.2.-3", "1.2.3-alpha_beta", " 1.2.3",
	}
	for _, s := range invalid {
		if Valid(s) {
			t.Fatalf("Valid(%q) = true, want false", s)
		}
	}
}

func TestPrecedenceChain(t *testing.T) {
	// The ordering example from semver.org §11, ascending.
	chain := []string{
		"1.0.0-alpha", "1.0.0-alpha.1", "1.0.0-alpha.beta", "1.0.0-beta",
		"1.0.0-beta.2", "1.0.0-beta.11", "1.0.0-rc.1", "1.0.0",
	}
	for i := 0; i < len(chain)-1; i++ {
		a, err := parseSemver(chain[i])
		if err != nil {
			t.Fatalf("parse %q: %v", chain[i], err)
		}
		b, err := parseSemver(chain[i+1])
		if err != nil {
			t.Fatalf("parse %q: %v", chain[i+1], err)
		}
		if !(svCompare(b, a) > 0) {
			t.Fatalf("expected %q > %q", chain[i+1], chain[i])
		}
		if svCompare(a, b) > 0 {
			t.Fatalf("expected NOT %q > %q", chain[i], chain[i+1])
		}
	}
}

func TestBuildMetadataIgnored(t *testing.T) {
	a, _ := parseSemver("1.0.0+build.1")
	b, _ := parseSemver("1.0.0+build.2")
	if svCompare(a, b) != 0 {
		t.Fatalf("build metadata must not affect precedence")
	}
}

func TestBumpClass(t *testing.T) {
	cases := []struct{ from, to, want string }{
		{"", "0.1.0", "genesis"},
		{"1.0.0", "2.0.0", "major"},
		{"1.0.0", "1.1.0", "minor"},
		{"1.0.0", "1.0.1", "patch"},
		{"1.0.0", "1.0.0", ""},
		{"1.2.0", "1.1.9", ""},
		{"1.0.0-rc.1", "1.0.0", "patch"},
		{"1.0.0", "1.0.0-rc.1", ""},
	}
	for _, c := range cases {
		if got := BumpClass(c.from, c.to); got != c.want {
			t.Fatalf("BumpClass(%q,%q) = %q, want %q", c.from, c.to, got, c.want)
		}
	}
}

// TestLedgerLifecycle drives the state machine end to end: genesis, three
// bumps, then the two rejection paths that make the ledger trustworthy.
func TestLedgerLifecycle(cur realm, t *testing.T) {
	const me = "g1e73sfpdr5ulzcuv6e4wv973de2huhuyhx65rxy"
	testing.SetRealm(testing.NewUserRealm(me))

	Register(cross(cur), "tavern-kit")
	if got := Count("tavern-kit"); got != 0 {
		t.Fatalf("fresh project has %d releases, want 0", got)
	}

	r := Ship(cross(cur), "tavern-kit", "", "0.1.0", "first public cut")
	if r.Bump != "genesis" || r.Seq != 1 {
		t.Fatalf("genesis record = %+v", r)
	}
	if r.Author != me {
		t.Fatalf("author = %q, want caller %q", r.Author, me)
	}

	if r := Ship(cross(cur), "tavern-kit", "0.1.0", "0.2.0", "ledger render"); r.Bump != "minor" {
		t.Fatalf("0.1.0->0.2.0 classified %q", r.Bump)
	}
	if r := Ship(cross(cur), "tavern-kit", "0.2.0", "0.2.1", "escaping fix"); r.Bump != "patch" {
		t.Fatalf("0.2.0->0.2.1 classified %q", r.Bump)
	}
	if r := Ship(cross(cur), "tavern-kit", "0.2.1", "1.0.0", "stable API"); r.Bump != "major" {
		t.Fatalf("0.2.1->1.0.0 classified %q", r.Bump)
	}

	if got := Count("tavern-kit"); got != 4 {
		t.Fatalf("count = %d, want 4", got)
	}
	if got, _ := Total(); got < 4 {
		t.Fatalf("total releases = %d, want >= 4", got)
	}
	last, ok := Latest("tavern-kit")
	if !ok || last.ToVersion != "1.0.0" {
		t.Fatalf("latest = %+v ok=%v", last, ok)
	}
}

// TestRejectsBrokenChain covers the property that makes this a chain rather
// than a bag of claims: `from` must be the version actually shipped last.
func TestRejectsBrokenChain(cur realm, t *testing.T) {
	const me = "g1e73sfpdr5ulzcuv6e4wv973de2huhuyhx65rxy"
	testing.SetRealm(testing.NewUserRealm(me))
	Register(cross(cur), "chain-test")
	Ship(cross(cur), "chain-test", "", "1.0.0", "start")

	if rec := revive(func() { Ship(cross(cur), "chain-test", "0.9.0", "1.0.1", "wrong from") }); rec == nil {
		t.Fatalf("expected panic when from does not match last shipped version")
	}
	if rec := revive(func() { Ship(cross(cur), "chain-test", "1.0.0", "1.0.0", "no increase") }); rec == nil {
		t.Fatalf("expected panic when version does not increase")
	}
	if rec := revive(func() { Ship(cross(cur), "chain-test", "1.0.0", "1.0.0-rc.1", "downgrade") }); rec == nil {
		t.Fatalf("expected panic on downgrade to prerelease")
	}
	if rec := revive(func() { Register(cross(cur), "chain-test") }); rec == nil {
		t.Fatalf("expected panic on duplicate registration")
	}
	if got := Count("chain-test"); got != 1 {
		t.Fatalf("rejected records mutated the ledger: count = %d, want 1", got)
	}
}

